(window.EX_CHUNKS=window.EX_CHUNKS||{})["b59"]={"零钱":[["我身上只有几块钱零钱。","مەندە پەقەت بىر نەچچە يۈەن پۇل بار.","mende peqet bir nechche yüen pul bar."]],"机灵":[["这孩子真机灵，总能想出好办法。","بۇ بالا ھەقىقەتەن زېرەك، ھەر ۋاقىت ياخشى ئامال تېپىپ چىقىدۇ.","bu bala heqiqeten zérek, her waqit yaxshi amal tépip chiqidu."]],"密封":[["这个罐子密封得很好，一点味道都漏不出来。","بۇ قاچا ناھايىتى ياخشى پېچەتلەنگەن، پۇرىقىمۇ سىرتقا چىقمايدۇ.","bu qacha nahayiti yaxshi péchetlengen, puriqimu sirtqa chiqmaydu."]],"皮革":[["这双皮鞋是用优质皮革制成的。","بۇ جۈپ كۆنەك تېرىكى ئەڭ ياخشى تېرەدىن ياسالغان.","bu jüp könek tériki eng yaxshi téredin yasalghan."]],"窍门":[["掌握窍门能让工作事半功倍。","ئۇسۇلنى ئىگىلەش خىزمەتنى ئىككى ھەسسە ئۈنۈملۈك قىلالايدۇ.","usulni igilesh xizmetni ikki hesse ünümlük qilalaydu."]],"外向":[["她性格外向，很受欢迎。","ئۇنىڭ خاراكتېرى ئوچۇق، ئۇ ناھايىتى ئالقىشقا ئېرىشتى.","uning xaraktéri ochuq, u nahayiti alqishqa érishti."]],"劻":[["他因一时冲动而犯下大错，深感劻悔。","ئۇ بىر ئازغىنە ھېسسىياتقا بېرىلىپ چوڭ خاتالىق سادىر قىلىپ، چوڭقۇر پۇشايمان چەكتى.","u bir azghine héssiyatqa bérilip chong xataliq sadir qilip, chongqur pushayman chekti."]],"扻":[["他用手扻住门不让关。","ئۇ قولى بىلەن ئىشىكنى تۇتۇپ قويۇپ يېپىلىشىغا يول قويمىدى.","u qoli bilen ishikni tutup qoyup yépilishigha yol qoymidi."]],"槻":[["槻树是一种很常见的树木。","ئارچا دەرىخى ئىنتايىن كۆپ ئۇچرايدىغان بىر خىل دەرەخ.","archa derixi intayin köp uchraydighan bir xil derex."]],"矻":[["他矻矻劳作。","ئۇ تىرىشىپ ئىشلىدى.","u tiriship ishlidi."]],"磻":[["古代用磻石制作工具。","قەدىمكى زاماندا سۈركىلىش تېشىدىن قورال ياساشقا ئىشلىتىلگەن.","qedimki zamanda sürkilish téshidin qoral yasashqa ishlitilgen."]],"痻":[["长期劳累引发痻疾。","ئۇزۇن مۇددەتلىك ھارغىنلىق سۇسلىق كېسىلىنى كەلتۈرۈپ چىقىرىدۇ.","uzun muddetlik harghinliq susliq késilini keltürüp chiqiridu."]],"粻":[["这种粻是南方特有的米种。","بۇ خىل گۈرۈچ جەنۇبقا خاس گۈرۈچ تۈرىدۇر.","bu xil gürüch jenubqa xas gürüch türidur."]],"菻":[["菻草是一种耐旱的灌木。","كۈنچىقار چاتقىلى قۇرغاقچىلىققا چىداملىق بىر خىل پەلەمپەيدۇر.","künchiqar chatqili qurghaqchiliqqa chidamliq bir xil pelempeydur."]],"蚻":[["蚻虫喜欢在夜间活动。","قۇرتقۇچ قۇرتى كېچىسى ھەرىكەت قىلىشنى ياخشى كۆرىدۇ.","qurtquch qurti kéchisi heriket qilishni yaxshi köridu."]],"詻":[["这种詻言在正式场合并不合适。","بۇ خىل يالغان سۆزلەر رەسمىي ئورۇنلاردا مۇۋاپىق ئەمەس.","bu xil yalghan sözler resmiy orunlarda muwapiq emes."]],"豻":[["豻是一种体型较小的犬科动物。","ئەن بەدەن تىپى كىچىكرەك ئىت ئائىلىسىدىكى ھايۋان.","en beden tipi kichikrek it ailisidiki haywan."]],"铻":[["铻在古代常用于武器。","قەدىمكى زامانلاردا بۇ خىل مېتال كۆپىنچە قورال-ياراغلاردا ئىشلىتىلگەن.","qedimki zamanlarda bu xil métal köpinche qoral-yaraghlarda ishlitilgen."]],"镻":[["镻在化学实验中常被用作催化剂。","دى چېمىيە تەجرىبىلىرىدە كۆپىنچە كاتالىزاتور سۈپىتىدە ئىشلىتىلىدۇ.","di chémiye tejribiliride köpinche katalizator süpitide ishlitilidu."]],"鸻":[["鸻鸟常在沙滩上觅食。","ھېڭ قۇشى كۆپىنچە قۇملىق ساھىلدا يەم-خەشەك ئىزدەيدۇ.","héng qushi köpinche qumliq sahilda yem-xeshek izdeydu."]],"鮻":[["鮻鱼在沿海地区常见。","كۈمۈش بېلىق دېڭىز بويى رايونلىرىدا كۆپ ئۇچرايدۇ.","kümüsh béliq déngiz boyi rayonlirida köp uchraydu."]],"一事无成":[["他一事无成，总是半途而废。","ئۇ ھېچ ئىشنى پۈتتۈرەلمىدى، ھەمىشە يېرىم يولدا تاشلاپ قويىدۇ.","u héch ishni püttürelmidi, hemishe yérim yolda tashlap qoyidu."]],"駻":[["駻马奔跑起来气势非凡。","قارا ئات چاپقاندا ھەيۋەتلىك.","qara at chapqanda heywetlik."]],"一神教":[["一神教强调对唯一神的信仰。","بىر ئىلاھلىق دىن يەككە ئىلاھقا ئېتىقاد قىلىشنى تەكىتلەيدۇ.","bir ilahliq din yekke ilahqa étiqad qilishni tekitleydu."]],"一笔抹杀":[["这种成就被一笔抹杀，令人遗憾。","بۇ خىل نەتىجە بىر قەلەم بىلەن يوققا چىقىرىلدى، ئەپسۇسلىنارلىق.","bu xil netije bir qelem bilen yoqqa chiqirildi, epsuslinarliq."]],"一板一眼":[["他做事一板一眼，从不马虎。","ئۇ ئىش قىلغاندا تەرتىپلىك، ھەرگىز سەل قارىمايدۇ.","u ish qilghanda tertiplik, hergiz sel qarimaydu."]],"一总":[["他是此次行动的一总负责人。","ئۇ بۇ قېتىمقى ھەرىكەتنىڭ باش مەسئۇلى.","u bu qétimqi heriketning bash mes'uli."]],"一般性":[["这件事具有普遍的一般性。","بۇ ئىش ئومۇمىي ئادەتتىكىلىك خاراكتېرىگە ئىگە.","bu ish omumiy adettikilik xaraktérige ige."]],"一路上":[["一路上风景优美，令人难忘。","يول بويى مەنزىرە گۈزەل، ئادەمنى ئۇنتۇلغۇسىز ھېسسىياتقا سالىدۇ.","yol boyi menzire güzel, ademni untulghusiz héssiyatqa salidu."]],"一视同仁":[["公司对员工一视同仁。","شىركەت خىزمەتچىلەرگە ئوخشاش مۇئامىلە قىلىدۇ.","shirket xizmetchilerge oxshash muamile qilidu."]],"三两":[["这道菜需要三两肉。","بۇ تائامغا ئۈچ سېرىق پۇت ئەت كېرەك.","bu taamgha üch sériq put et kérek."]],"不可能":[["这根本不可能实现。","بۇنى ئەسلا ئەمەلگە ئاشۇرغىلى بولمايدۇ.","buni esla emelge ashurghili bolmaydu."]],"鄻":[["鄻山是当地一个著名的旅游景点。","لەنشەن يەرلىكتە مەشھۇر بىر ساياھەت مەنزىلگاھى.","lenshen yerlikte meshhur bir sayahet menzilgahi."]],"下车":[["请从右侧下车。","ئوڭ تەرەپتىن ماشىنىدىن چۈشۈڭ.","ong tereptin mashinidin chüshüng."]],"丁型肝炎":[["丁型肝炎由丁型肝炎病毒引起，可通过血液传播。","D تىپلىق جىگەر ياللۇغى D تىپلىق جىگەر ياللۇغى ۋىرۇسىدىن كېلىپ چىقىدۇ، قان ئارقىلىق تارقىلىدۇ.","D tipliq jiger yallughi D tipliq jiger yallughi wirusidin kélip chiqidu, qan arqiliq tarqilidu."]],"上装":[["上装搭配下装要协调。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"不相符":[["数据结果与理论不相符。","سانلىق مەلۇمات نەتىجىسى نەزەرىيە بىلەن ماس كەلمەيدۇ.","sanliq melumat netijisi nezeriye bilen mas kelmeydu."]],"世界文化遗产地":[["故宫是世界文化遗产地。","گۇگۇڭ دۇنيا مەدەنىيەت مىراسى ئورنى.","gugung dunya medeniyet mirasi orni."]],"中气层顶":[["中气层顶是天气变化的关键区域。","ئوتتۇرا ھاۋا قاتلىمىنىڭ چوققىسى ھاۋا رايى ئۆزگىرىشىنىڭ مۇھىم رايونىدۇر.","ottura hawa qatlimining choqqisi hawa rayi özgirishining muhim rayonidur."]],"中间层":[["中间层负责数据传输。","ئوتتۇرا قاتلام سانلىق مەلۇمات يەتكۈزۈشكە مەسئۇل.","ottura qatlam sanliq melumat yetküzüshke mes'ul."]],"久别重逢":[["久别重逢，真是令人高兴。","ئۇزۇن ئايرىلىشتىن كېيىن قايتا كۆرۈشۈش ھەقىقەتەن خۇشاللىق.","uzun ayrilishtin kéyin qayta körüshüsh heqiqeten xushalliq."]],"中师":[["中师是中等师范学校的简称。","جۇڭشى ئوتتۇرا دەرىجىلىك پېداگوگىكا مەكتىپىنىڭ قىسقارتىلما ئاتىلىشىدۇر.","jungshi ottura derijilik pédagogika mektipining qisqartilma atilishidur."]],"干饭":[["大家快过来干饭吧！","ھەممىڭلار تېز كېلىڭلار، تاماق يەيلى!","hemminglar téz kélinglar, tamaq yeyli!"]],"二甘醇":[["二甘醇是一种重要的有机化合物。","دىئېتىلېن گلىكول مۇھىم ئورگانىك بىرىكمىدۇر.","diétilén glikol muhim organik birikmidur."]],"二醇":[["乙二醇是一种常见化学品。","ئېتىلېن گلىكول ئادەتتىكى خىمىيىلىك ماددىدۇر.","étilén glikol adettiki ximiyilik maddidur."]],"五经":[["《五经》是中国古代重要的儒家经典。","«ۋۇجىڭ» جۇڭگونىڭ قەدىمكى زامانىدىكى مۇھىم كونفۇچىلىق كلاسسىك ئەسىرى.","«wujing» junggoning qedimki zamanidiki muhim konfuchiliq klassik esiri."]],"五脏":[["五脏指人体中的五个主要器官。","بەش ئىچكى ئەزا ئىنسان بەدىنىدىكى بەش ئاساسلىق ئەزانى كۆرسىتىدۇ.","besh ichki eza insan bedinidiki besh asasliq ezani körsitidu."]],"井田":[["古代实行井田制度。","قەدىمكى زاماندا قۇدۇق-ئېتىز تۈزۈمى يولغا قويۇلغان.","qedimki zamanda quduq-étiz tüzümi yolgha qoyulghan."]],"五口通商":[["五口通商是清朝时期开放的五个通商口岸。","بەش ئېغىز سودا ئېچىش چىڭ سۇلالىسى دەۋرىدە ئېچىلغان بەش سودا پورتى.","besh éghiz soda échish ching sulalisi dewride échilghan besh soda porti."]],"二指":[["他用二指夹起桌上的小物件。","ئۇ ئىككى بارماقى بىلەن ئۈستەلدىكى كىچىك نەرسىنى قىستۇرۇۋالدى.","u ikki barmaqi bilen üsteldiki kichik nersini qisturuwaldi."]],"亚马逊河":[["亚马逊河拥有世界上最丰富的生物多样性。","ئامازون دەرياسى دۇنيادىكى ئەڭ باي بىئولوگىيىلىك كۆپ خىللىققا ئىگە.","amazon deryasi dunyadiki eng bay biologiyilik köp xilliqqa ige."]],"交款单":[["请填写交款单完成支付。","تۆلەم تالونىنى تولدۇرۇپ تۆلەمنى تاماملاڭ.","tölem talonini toldurup tölemni tamamlang."]],"交通警卫":[["交通警卫确保重要路段的安全。","قاتناش مۇھاپىزەتچىسى مۇھىم يول بۆلەكلىرىنىڭ بىخەتەرلىكىنى كاپالەتكە ئىگە قىلىدۇ.","qatnash muhapizetchisi muhim yol böleklirining bixeterlikini kapaletke ige qilidu."]],"交响乐团":[["这支交响乐团在国际比赛中屡获殊荣。","بۇ سىمفونىيە ئوركېستىرى خەلقئارا مۇسابىقىلەردە قايتا-قايتا شەرەپكە ئېرىشتى.","bu simfoniye orkéstiri xelq'ara musabiqilerde qayta-qayta sherepke érishti."]],"亮彩":[["亮彩的灯光吸引了众人目光。","يورۇق رەڭلىك چىراغلار كۆپچىلىكنىڭ دىققىتىنى تارتىپ قويدى.","yoruq renglik chiraghlar köpchilikning diqqitini tartip qoydi."]],"亭午":[["亭午时分，阳光洒满整个庭院，温暖而宁静。","چۈش ۋاقتى قۇياش نۇرى پۈتۈن ھويلىغا چاچىلىپ، ئىللىق ۋە جىمجىت ئىدى.","chüsh waqti quyash nuri pütün hoyligha chachilip, illiq we jimjit idi."]],"人口统计学":[["人口统计学是研究人口特征的科学。","نۇپۇس ستاتىستىكىسى نۇپۇس ئالاھىدىلىكلىرىنى تەتقىق قىلىدىغان پەن.","nupus statistikisi nupus alahidiliklirini tetqiq qilidighan pen."]],"代驾":[["代驾服务很受欢迎。","ئورۇن باسقۇچىلىق مۇلازىمىتى ئىنتايىن ئالقىشقا ئېرىشتى.","orun basquchiliq mulazimiti intayin alqishqa érishti."]],"付之丙丁":[["这些文件被付之丙丁，化为灰烬。","بۇ ھۆججەتلەر ئوتقا كۆيدۈرۈلۈپ، كۈلگە ئايلاندى.","bu höjjetler otqa köydürülüp, külge aylandi."]],"付梓":[["这部小说即将付梓出版。","بۇ رومان بېسىلىپ چىقىشقا تەييار.","bu roman bésilip chiqishqa teyyar."]],"伯劳鸟":[["伯劳鸟以昆虫为食。","بېرلا قۇشى ھاشارات بىلەن ئوزۇقلىنىدۇ.","bérla qushi hasharat bilen ozuqlinidu."]],"代客泊车":[["酒店提供代客泊车服务。","مېھمانخانا مېھمانلارنىڭ ئورنىغا ماشىنا توختىتىش مۇلازىمىتىنى تەمىنلەيدۇ.","méhmanxana méhmanlarning ornigha mashina toxtitish mulazimitini teminleydu."]],"作茧自缚":[["他的行为无异于作茧自缚。","ئۇنىڭ قىلمىشى ئۆزىگە تور توقۇش بىلەن باراۋەر.","uning qilmishi özige tor toqush bilen barawer."]],"佛家":[["佛家主张慈悲与智慧并重的修行方式。","بۇددا مەزھىبى رەھىمدىللىق بىلەن دانالىقنى تەڭ ئېتىبارغا ئالغان ئىبادەت ئۇسۇلىنى تەشەببۇس قىلىدۇ.","budda mezhibi rehimdilliq bilen danaliqni teng étibargha alghan ibadet usulini teshebbus qilidu."]],"伯里克利":[["伯里克利是雅典政治家。","پېرىكلىس ئافېنا سىياسەتچىسى.","périklis aféna siyasetchisi."]],"俗体字":[["俗体字在历史上曾被广泛使用。","ئاممىۋى يېزىق تارىختا كەڭ ئىشلىتىلگەن.","ammiwi yéziq tarixta keng ishlitilgen."]],"俊雅":[["他的举止俊雅，充满魅力。","ئۇنىڭ يۈرۈش-تۇرۇشى نەپىس، جەلپكارلىققا تولغان.","uning yürüsh-turushi nepis, jelpkarliqqa tolghan."]],"保力龙":[["保力龙品牌深受消费者喜爱。","باۋلىلۇڭ ماركىسى ئىستېمالچىلارنىڭ ياقتۇرۇشىغا ئېرىشتى.","bawlilung markisi istémalchilarning yaqturushigha érishti."]],"保护剂":[["这种保护剂能有效防止皮肤老化。","بۇ خىل قوغداش دورىسى تېرىنىڭ قېرىشىنى ئۈنۈملۈك ئالدىنى ئالالايدۇ.","bu xil qoghdash dorisi térining qérishini ünümlük aldini alalaydu."]],"信不过":[["我完全信不过他的承诺。","مەن ئۇنىڭ ۋەدىسىگە پۈتۈنلەي ئىشەنمەيمەن.","men uning wedisige pütünley ishenmeymen."]],"修成正果":[["经过努力，他终于修成正果。","تىرىشچانلىق بىلەن ئۇ ئاخىرى ئەڭ يۇقىرى نەتىجىگە ئېرىشتى.","tirishchanliq bilen u axiri eng yuqiri netijige érishti."]],"假动作":[["他的假动作骗过了对手。","ئۇنىڭ يالغان ھەرىكىتى رەقىبىنى ئالدىدى.","uning yalghan herikiti reqibini aldidi."]],"偏航":[["飞机偏航了，需要立即纠正。","ئايروپىلان يولىدىن ئېغىپ كەتتى، دەرھال تۈزىتىش كېرەك.","ayropilan yolidin éghip ketti, derhal tüzitish kérek."]],"健检":[["医生建议定期健检。","دوختۇر قەرەللىك ساغلاملىق تەكشۈرۈشىنى تەۋسىيە قىلدى.","doxtur qerellik saghlamliq tekshürüshini tewsiye qildi."]],"偷排":[["工厂偷排污水，污染环境。","زاۋۇت ئەخلەت سۇنى يوشۇرۇن ئاققۇزۇپ، مۇھىتنى بۇلغىدى.","zawut exlet suni yoshurun aqquzup, muhitni bulghidi."]],"偷渡者":[["偷渡者面临严厉处罚。","يوشۇرۇن ئۆتكۈنچىلەر قاتتىق جازاغا دۇچ كېلىدۇ.","yoshurun ötkünchiler qattiq jazagha duch kélidu."]],"借出":[["银行将资金借出给企业。","بانكا مەبلەغنى كارخانىلارغا قەرزگە بېرىدۇ.","banka mebleghni karxanilargha qerzge béridu."]],"借刀杀人":[["他借刀杀人，间接除掉对手。","ئۇ باشقىلارنىڭ پىچىقى بىلەن ئۆلتۈرۈپ، رەقىبىنى بىۋاسىتە ئوتتۇرىدىن يوقاتتى.","u bashqilarning pichiqi bilen öltürüp, reqibini biwasite otturidin yoqatti."]],"借译词":[["这个借译词在翻译中很常见。","بۇ قەرز تەرجىمە سۆزى تەرجىمىدە ئىنتايىن كۆپ ئۇچرايدۇ.","bu qerz terjime sözi terjimide intayin köp uchraydu."]],"催泪弹":[["催泪弹用于驱散人群。","كۆز ياشلىتىش بومبىسى ئاممىنى تارقىتىشقا ئىشلىتىلىدۇ.","köz yashlitish bombisi ammini tarqitishqa ishlitilidu."]],"催产":[["医生使用药物进行催产。","دوختۇر دورا ئىشلىتىپ تۇغدۇرىدۇ.","doxtur dora ishlitip tughduridu."]],"催眠药":[["这种催眠药效果非常显著。","بۇ خىل ھىپنوز دورىسىنىڭ ئۈنۈمى ئىنتايىن كۆرۈنەرلىك.","bu xil hipnoz dorisining ünümi intayin körünerlik."]],"催眠术":[["表演者用催眠术让观众配合。","ئىپادىلىگۈچى ھىپنوز تېخنىكىسى بىلەن تاماشىبىنلارنى ھەمكارلاشتۇردى.","ipadiligüchi hipnoz téxnikisi bilen tamashibinlarni hemkarlashturdi."]],"传输速率":[["传输速率直接影响数据质量。","يەتكۈزۈش سۈرئىتى سانلىق مەلۇمات سۈپىتىگە بىۋاسىتە تەسىر كۆرسىتىدۇ.","yetküzüsh sür'iti sanliq melumat süpitige biwasite tesir körsitidu."]],"兄长":[["兄长，您最近身体如何？","ئاكا، يېقىندىن بۇيان بەدەن ساغلاملىقىڭىز قانداق؟","aka, yéqindin buyan beden saghlamliqingiz qandaq?"]],"储物柜":[["储物柜里放着他的日常用品。","ئەشيا ساقلاش ئىشكىنىدە ئۇنىڭ كۈندىلىك بۇيۇملىرى بار.","eshya saqlash ishkinide uning kündilik buyumliri bar."]],"允宜":[["这种做法允宜且合理。","بۇ خىل ئۇسۇل مۇۋاپىق ۋە ئورۇنلۇقتۇر.","bu xil usul muwapiq we orunluqtur."]],"元神":[["游戏中的元神角色深受玩家喜爱。","ئويۇندىكى يۈەنشېن رولى ئويۇنچىلارنىڭ ياخشى كۆرۈشىگە ئېرىشكەن.","oyundiki yüenshén roli oyunchilarning yaxshi körüshige érishken."]],"免票":[["儿童可以免票进入。","بالىلار بېلەتسىز كىرەلەيدۇ.","balilar béletsiz kireleydu."]],"克耶邦":[["克耶邦是缅甸的一个邦。","كرىۋېتسا شتاتى بىرمانىڭ بىر شتاتىدۇر.","kriwétsa shtati birmaning bir shtatidur."]],"入禀":[["他向官府入禀了此事。","ئۇ بۇ ئىشنى ھۆكۈمەت ئورگىنىغا ئەرز قىلدى.","u bu ishni hökümet orginigha erz qildi."]],"全面禁止":[["政府决定全面禁止使用一次性塑料制品。","ھۆكۈمەت بىر قېتىملىق پلاستىك بۇيۇملارنى پۈتۈن يۈزلۈك چەكلەشكە قارار قىلدى.","hökümet bir qétimliq plastik buyumlarni pütün yüzlük chekleshke qarar qildi."]],"八大菜系":[["中国有八大菜系，各具特色。","جۇڭگودا سەككىز چوڭ تاماق تۈرى بار، ھەر بىرى ئۆزگىچە ئالاھىدىلىككە ئىگە.","junggoda sekkiz chong tamaq türi bar, her biri özgiche alahidilikke ige."]],"八婆":[["她整天像个八婆一样八卦。","ئۇ كۈن بويى سەككىز پەرزەنتلىك ئايالغا ئوخشاش پەرەز قىلىدۇ.","u kün boyi sekkiz perzentlik ayalgha oxshash perez qilidu."]],"八字方针":[["八字方针是重要的政策指导。","سەككىز خەت فاڭجېنى مۇھىم سىياسەت يېتەكچىسى.","sekkiz xet fangjéni muhim siyaset yétekchisi."]],"八家将":[["八家将是中国传统戏剧中的角色组合。","سەككىز ئائىلە سەردارى جۇڭگو ئەنئەنىۋى تىياتىرىدىكى روللار گۇرۇھى.","sekkiz aile serdari junggo en'eniwi tiyatiridiki rollar guruhi."]],"内传":[["球队的内传配合十分流畅。","كوماندىنىڭ ئىچكى پاس چەمبىرىكى ئىنتايىن راۋان.","komandining ichki pas chembiriki intayin rawan."]],"八级工资制":[["八级工资制是旧中国的工资制度。","سەككىز دەرىجىلىك ئاشلىق سىستېمىسى كونا جۇڭگونىڭ ئاشلىق تۈزۈمىدۇر.","sekkiz derijilik ashliq sistémisi kona junggoning ashliq tüzümidur."]],"八般头风":[["八般头风是一种复杂的头痛类型。","سەككىز خىل باش ئاغرىقى مۇرەككەپ بىر خىل باش ئاغرىقى تىپىدۇر.","sekkiz xil bash aghriqi murekkep bir xil bash aghriqi tipidur."]],"两虎相争":[["两虎相争，往往导致两败俱伤。","ئىككى يولۋاس ئېلىشسا، كۆپىنچە ئىككىسى تەڭ زىيان تارتىدۇ.","ikki yolwas élishsa, köpinche ikkisi teng ziyan tartidu."]],"公理法":[["公理法是证明定理的基础方法。","ئاكسىيوم ئۇسۇلى نەزەرىيەنى ئىسپاتلاشنىڭ ئاساسىي ئۇسۇلى.","aksiyom usuli nezeriyeni ispatlashning asasiy usuli."]],"八正道":[["八正道是佛教修行的核心原则。","سەككىز توغرا يول بۇددا دىنى ئەمەلىياتىنىڭ يادرولۇق پرىنسىپى.","sekkiz toghra yol budda dini emeliyatining yadroluq prinsipi."]],"六合":[["他们追求六合彩的幸运数字。","ئۇلار ئالتە بىرلەشمە لوتېرىيىنىڭ بەختلىك سانلىرىنى ئىزدەيدۇ.","ular alte birleshme lotériyining bextlik sanlirini izdeydu."]],"六月":[["六月是夏季最炎热的月份之一。","ئالتىنچى ئاي يازنىڭ ئەڭ ئىسسىق ئايلىرىنىڭ بىرىدۇر.","altinchi ay yazning eng issiq aylirining biridur."]],"冀朝铸":[["冀朝铸是一位历史学家。","جى چاۋجۇ بىر تارىخچى.","ji chawju bir tarixchi."]],"兼具":[["这款手机兼具时尚与实用。","بۇ تېلېفون ھەم مودا ھەم ئەمەلىي.","bu téléfon hem moda hem emeliy."]],"兵源":[["兵源充足是军队壮大的基础。","ھەربىي كۈچ مەنبەسىنىڭ يېتەرلىك بولۇشى ئارمىيەنىڭ كۈچىيىشىنىڭ ئاساسىدۇر.","herbiy küch menbesining yéterlik bolushi armiyening küchiyishining asasidur."]],"冷媒":[["这种冷媒能高效降低温度。","بۇ خىل سوغۇتقۇچ ماددا تېمپېراتۇرىنى يۇقىرى ئۈنۈم بىلەن تۆۋەنلىتەلەيدۇ.","bu xil soghutquch madda témpératurini yuqiri ünüm bilen töwenliteleydu."]],"分时多工":[["分时多工是早期的计算机功能。","ۋاقىت بۆلۈش كۆپ ۋەزىپىلىك ئىجرا ئەسلىدە كومپيۇتېرنىڭ ئىقتىدارى ئىدى.","waqit bölüsh köp wezipilik ijra eslide kompyutérning iqtidari idi."]],"分析人士":[["分析人士认为市场会反弹。","تەھلىلچىلەر بازارنىڭ قايتىدىن كۆتۈرۈلىدىغانلىقىنى قارايدۇ.","tehlilchiler bazarning qaytidin kötürülidighanliqini qaraydu."]],"制钱":[["古代用铜制钱。","قەدىمدە مىس پۇل ئىشلىتىلگەن.","qedimde mis pul ishlitilgen."]],"前哨":[["前哨站负责警戒。","ئالدىنقى قاراۋۇلخانا مۇھاپىزەتچىلىك بىلەن شۇغۇللىنىدۇ.","aldinqi qarawulxana muhapizetchilik bilen shughullinidu."]],"剧本杀":[["我们昨晚玩了一场剧本杀游戏。","بىز تۈنۈگۈن كەچتە بىر مەيدان سېنارىيە-ئۆلتۈرۈش ئويۇنى ئوينىدۇق.","biz tünügün kechte bir meydan sénariye-öltürüsh oyuni oyniduq."]],"切换":[["切换不同的模式。","Okhshimighan rېjimlәrni almashturung.","Okhshimighan réjimlәrni almashturung."]],"利雅德":[["利雅德位于沙特阿拉伯。","رىياد سەئۇدى ئەرەبىستانىدا جايلاشقان.","riyad seudi erebistanida jaylashqan."]],"剪报":[["他经常剪报来收集新闻资料。","ئۇ خەۋەر ماتېرىياللىرىنى توپلاش ئۈچۈن گېزىت قىرقىشنى دائىم قىلىدۇ.","u xewer matériyallirini toplash üchün gézit qirqishni daim qilidu."]],"剪接":[["剪辑师对视频进行了精心的剪接。","قىرقىغۇچى سىنغا ئىنچىكە قىرقىش ئېلىپ باردى.","qirqighuchi singha inchike qirqish élip bardi."]],"剪草机":[["他用剪草机修剪了花园的草坪。","ئۇ چۆپ قىرقىغۇچ بىلەن باغچىنىڭ چىملىقىنى قىرقىدى.","u chöp qirqighuch bilen baghchining chimliqini qirqidi."]],"副作用":[["这种药可能有轻微的副作用。","بۇ دورا يېنىك يان تەسىرگە ئىگە بولۇشى مۇمكىن.","bu dora yénik yan tesirge ige bolushi mumkin."]],"加减乘除":[["加减乘除是四则基本运算。","قوشۇش، ئېلىش، كۆپەيتىش، بۆلۈش تۆت ئاساسىي ھېسابلاش.","qoshush, élish, köpeytish, bölüsh töt asasiy hésablash."]],"加进":[["把新成员加进团队中。","يېڭى ئەزالىرىنى گۇرۇپپىغا قوشۇڭ.","yéngi ezalirini guruppigha qoshung."]],"胜仗":[["军队赢得了这场胜仗。","ئارمىيە بۇ غەلىبىلىك ئۇرۇشنى ئۇتتى.","armiye bu ghelibilik urushni utti."]],"胜算":[["他们几乎没有胜算。","ئۇلارنىڭ غەلىبە قازىنىش ئېھتىماللىقى ئاساسەن يوق.","ularning ghelibe qazinish éhtimalliqi asasen yoq."]],"加赛":[["比赛结束后还安排了加赛环节。","مۇسابىقە ئاخىرلاشقاندىن كېيىن قوشۇمچە مۇسابىقە باسقۇچىمۇ ئورۇنلاشتۇرۇلدى.","musabiqe axirlashqandin kéyin qoshumche musabiqe basquchimu orunlashturuldi."]],"创收":[["公司通过创新实现了创收。","شىركەت يېڭىلىق يارىتىش ئارقىلىق كىرىم ياراتتى.","shirket yéngiliq yaritish arqiliq kirim yaratti."]],"功高不赏":[["功高不赏，实为不公。","تۆھپىسى يۇقىرى بولسىمۇ مۇكاپاتلانمىسا، بۇ ھەقىقەتەن ئادىل ئەمەس.","töhpisi yuqiri bolsimu mukapatlanmisa, bu heqiqeten adil emes."]],"勤务员":[["勤务员协助处理日常事务。","خىزمەتچى كۈندىلىك ئىشلارنى بىر تەرەپ قىلىشقا ياردەم بېرىدۇ.","xizmetchi kündilik ishlarni bir terep qilishqa yardem béridu."]],"北史":[["《北史》记载了北朝的历史。","«شىمالىي تارىخ» شىمالىي سۇلالىلەرنىڭ تارىخىنى خاتىرىلىگەن.","«shimaliy tarix» shimaliy sulalilerning tarixini xatiriligen."]],"北美洲":[["北美洲是最大的洲之一。","شىمالىي ئامېرىكا ئەڭ چوڭ قىتئەلەرنىڭ بىرى.","shimaliy amérika eng chong qit'elerning biri."]],"北湖区":[["北湖区是郴州市的中心区域。","بېيهۇ رايونى چېنژۇ شەھىرىنىڭ مەركىزىي رايونى.","béyeu rayoni chénzhu shehirining merkiziy rayoni."]],"卡塔赫纳":[["卡塔赫纳是哥伦比亚的港口城市。","كارتاخېنا كولومبىيەنىڭ پورت شەھىرى.","kartaxéna kolombiyening port shehiri."]],"却是":[["你说是他？却是我搞错了。","سەن ئۇنى دەيسەن؟ ئەمەلىيەتتە مەن خاتالاشتىم.","sen uni deysen? emeliyette men xatalashtim."]],"去取":[["他在去取物品时，发现东西已经被别人拿走了。","ئۇ بۇيۇملارنى ئېلىپ كېلىشكە بارغاندا، نەرسىلەرنىڭ باشقىلار تەرىپىدىن ئېلىپ كېتىلگەنلىكىنى بايقىدى.","u buyumlarni élip kélishke barghanda, nersilerning bashqilar teripidin élip kétilgenlikini bayqidi."]],"反智主义":[["反智主义阻碍科学进步。","ئەقىلگە قارشىلىق ئىلمىي تەرەققىياتقا توسالغۇ بولىدۇ.","eqilge qarshiliq ilmiy tereqqiyatqa tosalghu bolidu."]],"卵子":[["卵子是生殖细胞。","تۇخۇم ھۈجەيرىسى كۆپىيىش ھۈجەيرىسىدۇر.","tuxum hüjeyrisi köpiyish hüjeyrisidur."]],"卵黄囊":[["卵黄囊储存着胚胎所需的营养。","تۇخۇم سېرىق خالتىسى ئېمبىرىيونغا كېرەكلىك ئوزۇقلۇقنى ساقلايدۇ.","tuxum sériq xaltisi émbiriyongha kéreklik ozuqluqni saqlaydu."]],"南湖区":[["南湖区有许多历史古迹。","نەنھۇ رايونىدا نۇرغۇن تارىخىي يادىكارلىقلار بار.","nenhu rayonida nurghun tarixiy yadikarliqlar bar."]],"南征北讨":[["南征北讨指四处征讨敌人。","جەنۇبقا يۈرۈش شىمالغا ئاتلىنىش تۆت تەرەپتە دۈشمەنگە جەڭ ئېلان قىلىشنى كۆرسىتىدۇ.","jenubqa yürüsh shimalgha atlinish töt terepte düshmenge jeng élan qilishni körsitidu."]],"卡式炉":[["卡式炉适合户外露营时使用。","كارا تىپلىق ئوچاق سىرتقا چىقىپ دالا مۇساپىسىدە ئىشلىتىشكە ماس.","kara tipliq ochaq sirtqa chiqip dala musapiside ishlitishke mas."]],"取保释放":[["他通过取保释放暂时离开了监狱。","ئۇ كاپالەتكە بېرىلىپ قويۇپ بېرىلىش ئارقىلىق تۈرمىدىن ۋاقىتلىق ئايرىلدى.","u kapaletke bérilip qoyup bérilish arqiliq türmidin waqitliq ayrildi."]],"口水歌":[["这首歌是典型的口水歌。","بۇ ناخشا تىپىك ئېغىز ناخشىسى.","bu naxsha tipik éghiz naxshisi."]],"取笑":[["不要取笑别人的缺点。","باشقىلارنىڭ كەمچىلىكىنى مازاق قىلماڭ.","bashqilarning kemchilikini mazaq qilmang."]],"受降仪式":[["受降仪式庄重肃穆。","تەسلىم بولۇش مۇراسىمى تەنتەنىلىك ۋە مۇراسىمىي بولدى.","teslim bolush murasimi tentenilik we murasimiy boldi."]],"叫醒服务":[["酒店提供叫醒服务，方便客人起床。","مېھمانخانا مېھمانلارنىڭ ئورنىدىن تۇرۇشىغا قولايلىق يارىتىپ، ئويغىتىش مۇلازىمىتى تەمىنلەيدۇ.","méhmanxana méhmanlarning ornidin turushigha qolayliq yaritip, oyghitish mulazimiti teminleydu."]],"古文运动":[["古文运动倡导回归古典风格。","قەدىمكى يازما ھەرىكىتى كلاسسىك ئۇسلۇبقا قايتىشنى تەشەببۇس قىلغان.","qedimki yazma herikiti klassik uslubqa qaytishni teshebbus qilghan."]],"台北市":[["台北市高楼林立。","تەيبېي شەھىرىدە ئېگىز بىنالار كۆپ.","teybéy shehiride égiz binalar köp."]],"可持续":[["我们需要可持续的发展。","بىزگە داۋاملىق تەرەققىيات كېرەك.","bizge dawamliq tereqqiyat kérek."]],"反义字":[["生”的反义字是“死”。","«تۇغۇلۇش» نىڭ ئەكس مەنىلىك خېتى «ئۆلۈم» دۇر.","«tughulush» ning eks menilik xéti «ölüm» dur."]],"反骨":[["这种反骨精神令人敬佩。","بۇ خىل ئەكس روھ كىشىنى ھەيران قالدۇرىدۇ.","bu xil eks roh kishini heyran qalduridu."]],"可读性":[["文章的可读性直接影响理解。","ماقالىنىڭ ئوقۇشچانلىقى چۈشىنىشكە بىۋاسىتە تەسىر كۆرسىتىدۇ.","maqalining oqushchanliqi chüshinishke biwasite tesir körsitidu."]],"可惊":[["这个消息令人可惊。","بۇ خەۋەر كىشىنى ھەيران قالدۇرىدۇ.","bu xewer kishini heyran qalduridu."]],"司陶特":[["司陶特是一种黑啤酒。","ستاۋت بىر خىل قارا پىۋا.","stawt bir xil qara piwa."]],"吃不来":[["这种复杂的菜，我实在吃不来。","بۇنداق مۇرەككەپ تاماقنى مەن ھەقىقەتەن تەييارلىيالمايمەن.","bundaq murekkep tamaqni men heqiqeten teyyarliyalmaymen."]],"名表":[["这块名表价值连城。","بۇ ئاتاقلىق قول سائىتى باھاسىز قىممەتكە ئىگە.","bu ataqliq qol saiti bahasiz qimmetke ige."]],"名门":[["他出身于名门世家。","ئۇ ئاتاقلىق ئائىلىدىن كەلگەن.","u ataqliq ailidin kelgen."]],"名缰利锁":[["他挣脱了名缰利锁的束缚。","ئۇ نام-شۆھرەت ۋە بايلىق كىشەنلىرىدىن قۇتۇلدى.","u nam-shöhret we bayliq kishenliridin qutuldi."]],"吞拿鱼":[["吞拿鱼富含优质蛋白质。","تۇنا بېلىقى يۇقىرى سۈپەتلىك ئاقسىلغا باي.","tuna béliqi yuqiri süpetlik aqsilgha bay."]],"否决票":[["他投下了否决票。","ئۇ ۋېتو بېلەت تاشلىدى.","u wéto bélet tashlidi."]],"合情合理":[["他的解释合情合理。","ئۇنىڭ چۈشەندۈرۈشى ئەقىلگە مۇۋاپىق.","uning chüshendürüshi eqilge muwapiq."]],"名山县":[["名山县风景优美。","مىڭشەن ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","mingshen nahiyisining menzirisi güzel."]],"名扬四海":[["他的才华已名扬四海。","ئۇنىڭ تالانتى تۆت دۇنياۋى داڭق چىقارغان.","uning talanti töt dunyawi dangq chiqarghan."]],"同班同学":[["同班同学之间要互相支持。","ساۋاقداشلار بىر-بىرىنى قوللىشى كېرەك.","sawaqdashlar bir-birini qollishi kérek."]],"周口":[["周口是中国的一个城市。","جۇكۇ جۇڭگونىڭ بىر شەھىرى.","juku junggoning bir shehiri."]],"呈阴性":[["检测结果呈阴性，说明没有感染。","تەكشۈرۈش نەتىجىسى سەلبىي بولۇپ، يۇقۇملانمىغانلىقىنى كۆرسەتتى.","tekshürüsh netijisi selbiy bolup, yuqumlanmighanliqini körsetti."]],"吹孔":[["吹孔的位置对音色影响很大。","نەي چېلىش تۆشۈكىنىڭ ئورنى ئاۋاز تۈسىگە چوڭ تەسىر كۆرسىتىدۇ.","ney chélish töshükining orni awaz tüsige chong tesir körsitidu."]],"吹气":[["用力吹气，气球就鼓起来了。","كۈچ بىلەن پۈۋلەپ، شار پۈۋلەپ كۆپۈپ چىقتى.","küch bilen püwlep, shar püwlep köpüp chiqti."]],"周代":[["周代是中国历史上的一个重要时期。","جۇ دەۋرى جۇڭگو تارىخىدىكى مۇھىم بىر دەۋر.","ju dewri junggo tarixidiki muhim bir dewr."]],"哈勃":[["哈勃望远镜发现了遥远星系。","ھاببىل تېلېسكوپى يىراق گالاكتىكىلارنى بايقىدى.","habbil téléskopi yiraq galaktikilarni bayqidi."]],"含沙射影":[["他的话含沙射影，令人不快。","ئۇنىڭ سۆزلىرى يوشۇرۇن مەنە بىلەن قىلىنغان بولۇپ، كىشىنى بىئارام قىلىدۇ.","uning sözliri yoshurun mene bilen qilinghan bolup, kishini biaram qilidu."]],"含油岩":[["含油岩是石油勘探的关键。","نېفىت تەركىبلىك تاش نېفىت ئىزدەشنىڭ ئاچقۇچىدۇر.","néfit terkiblik tash néfit izdeshning achquchidur."]],"唐敬宗":[["唐敬宗的统治时间非常短暂。","تاڭ جىڭزۇڭنىڭ ھۆكۈمرانلىق ۋاقتى ئىنتايىن قىسقا ئىدى.","tang jingzungning hökümranliq waqti intayin qisqa idi."]],"唐宋":[["唐宋时期是中国文化的黄金时代。","تاڭ-سۇڭ دەۋرى جۇڭگو مەدەنىيىتىنىڭ ئالتۇن دەۋرى.","tang-sung dewri junggo medeniyitining altun dewri."]],"商品化":[["产品正在商品化。","مەھسۇلات مالغا ئايلاندۇرۇلۇۋاتىدۇ.","mehsulat malgha aylanduruluwatidu."]],"啄木鸟":[["啄木鸟在树上啄食。","ياغاچچى قۇش دەرەختە تۇمشۇقلاپ يەۋاتىدۇ.","yaghachchi qush derexte tumshuqlap yewatidu."]],"哪知":[["哪知事情会这样发展？","قەيەردىن بىلەي ئىش بۇنداق تەرەققىي قىلىدۇ دەپ؟","qeyerdin biley ish bundaq tereqqiy qilidu dep?"]],"单倍体":[["这种植物的单倍体染色体数目较少。","بۇ ئۆسۈملۈكنىڭ گاپلوئىد خромوسوما سانى بىر قەدەر ئاز.","bu ösümlükning gaploid xромosoma sani bir qeder az."]],"嘴软":[["他嘴软，容易妥协。","ئۇنىڭ ئاغزى يۇمشاق، ئاسانلا ماقۇل بولىدۇ.","uning aghzi yumshaq, asanla maqul bolidu."]],"喷洒":[["他喷洒了杀虫剂。","ئۇ پەرۋىش دورىسى پۈركۈدى.","u perwish dorisi pürküdi."]],"单点故障":[["单点故障风险高。","بىر نۇقتىلىق ئۈزۈلۈش خەۋپى يۇقىرى.","bir nuqtiliq üzülüsh xewpi yuqiri."]],"四时":[["四时更替，景色也随之变化。","تۆت پەسىل ئالمىشىپ، مەنزىرىمۇ شۇنىڭغا ئەگىشىپ ئۆزگىرىدۇ.","töt pesil almiship, menzirimu shuninggha egiship özgiridu."]],"回教":[["回教在东南亚地区影响深远。","ئىسلام دىنى جەنۇبىي شەرقىي ئاسىيادا چوڭقۇر تەسىرگە ئىگە.","islam dini jenubiy sherqiy asiyada chongqur tesirge ige."]],"圈状物":[["这个圈状物是手工制作的。","بۇ چەمبىرەك شەكىللىك نەرسە قولدا ياسالغان.","bu chembirek shekillik nerse qolda yasalghan."]],"国定假日":[["国定假日让人们有机会放松休息。","دۆلەت بەلگىلىگەن بايرام كۈنلىرى كىشىلەرگە ئارام ئېلىش پۇرسىتى بېرىدۇ.","dölet belgiligen bayram künliri kishilerge aram élish pursiti béridu."]],"土建":[["他从事土建工作多年。","ئۇ توپا قۇرۇلۇش خىزمىتى بىلەن كۆپ يىل شۇغۇللانغان.","u topa qurulush xizmiti bilen köp yil shughullanghan."]],"土老帽":[["他是个典型的土老帽。","ئۇ بىر تىپىك تۇلاۋماودۇر.","u bir tipik tulawmaodur."]],"团体行":[["团体行很顺利。","گۇرۇپپا سەپىرى بەك راۋان ئۆتتى.","guruppa sepiri bek rawan ötti."]],"土人":[["这里的土人热情好客。","بۇ يەردىكى توپا كىشىلەر مېھماندوست.","bu yerdiki topa kishiler méhmandost."]],"坐收渔利":[["他坐收渔利，轻松获利。","ئۇ ئولتۇرۇپ پايدا ئېلىپ، ئاسانلىقچە پايدا ئالدى.","u olturup payda élip, asanliqche payda aldi."]],"坐下":[["请坐下，别站着说话。","ئولتۇرۇڭ، تۇرۇپ سۆزلەشمەڭ.","olturung, turup sözleshmeng."]],"坐冷板凳":[["他被教练安排坐冷板凳。","ئۇ مۇرەببىي تەرىپىدىن سوغۇق ئورۇندۇقتا ئولتۇرۇشقا تەيىنلەندى.","u murebbiy teripidin soghuq orunduqta olturushqa teyinlendi."]],"埃及夜鹰":[["这种埃及夜鹰的叫声非常独特。","بۇ خىل مىسىر كېچە قۇشىنىڭ ئاۋازى ئىنتايىن ئالاھىدە.","bu xil misir kéche qushining awazi intayin alahide."]],"埃迪卡拉纪":[["埃迪卡拉纪是地质历史上的重要时期。","ئېدىئاكارا دەۋرى گېئولوگىيە تارىخىدىكى مۇھىم بىر دەۋر.","édiakara dewri géologiye tarixidiki muhim bir dewr."]],"城中区":[["城中区是城市的核心区域。","شەھەر ئوتتۇرا رايونى شەھەرنىڭ يادرو رايونىدۇر.","sheher ottura rayoni sheherning yadro rayonidur."]],"地牛翻身":[["地牛翻身形容局势彻底逆转。","يەر تەۋرىشى ۋەزىيەتنىڭ پۈتۈنلەي ئۆزگىرىشىنى تەسۋىرلەيدۇ.","yer tewrishi weziyetning pütünley özgirishini teswirleydu."]],"坚强不屈":[["面对困难，他坚强不屈。","قىيىنچىلىققا دۇچ كەلگەندە، ئۇ جىيەنچياڭ بۇكلەنمەيدۇ.","qiyinchiliqqa duch kelgende, u jiyenchyang buklenmeydu."]],"塔塔尔族":[["塔塔尔族是中国的一个少数民族。","تاتار مىللىتى جۇڭگونىڭ ئاز سانلىق مىللەتلىرىنىڭ بىرىدۇر.","tatar milliti junggoning az sanliq milletlirining biridur."]],"坞站":[["这个坞站设备齐全。","بۇ بېكىتىش پونكىتىنىڭ ئۈسكۈنىلىرى تولۇق.","bu békitish ponkitining üsküniliri toluq."]],"填密":[["密码填密后更安全。","پارول تولدۇرۇلغاندىن كېيىن تېخىمۇ بىخەتەر بولىدۇ.","parol toldurulghandin kéyin téximu bixeter bolidu."]],"塞尔维亚克罗地亚语":[["塞尔维亚克罗地亚语是南斯拉夫时期的通用语言。","سېربىيە-كىرودىيە تىلى يۇگوسلاۋىيە دەۋرىدىكى ئورتاق تىل ئىدى.","sérbiye-kirodiye tili yugoslawiye dewridiki ortaq til idi."]],"塞牙":[["他吃饭时不小心塞牙了。","ئۇ تاماق يېگەندە سەۋەنسىز چىشىغا گۆش قىستىلىپ قالدى.","u tamaq yégende sewensiz chishigha gösh qistilip qaldi."]],"塞给":[["他把文件塞给秘书处理。","ئۇ ھۆججەتنى كاتىپقا بېرىپ بىر تەرەپ قىلدۇردى.","u höjjetni katipqa bérip bir terep qildurdi."]],"坟场":[["坟场位于城市的边缘。","قەبرىستانلىق شەھەرنىڭ چېتىدە جايلاشقان.","qebristanliq sheherning chétide jaylashqan."]],"墨匣":[["这款墨匣能持续打印数千页。","بۇ سىياھ قۇتىسى مىڭلىغان بەتنى داۋاملىق بېسىپ چىقالايدۇ.","bu siyah qutisi minglighan betni dawamliq bésip chiqalaydu."]],"压克力":[["这种压克力材质非常耐用。","بۇ خىل ئاكرىل ماتېرىيالى ئىنتايىن چىداملىق.","bu xil akril matériyali intayin chidamliq."]],"报复心":[["他因受挫而产生了强烈的报复心。","ئۇ مەغلۇبىيەتكە ئۇچرىغاچقا كۈچلۈك ئىنتىقام تۇيغۇسى پەيدا قىلدى.","u meghlubiyetke uchrighachqa küchlük intiqam tuyghusi peyda qildi."]],"外甥女婿":[["外甥女婿帮家里搬东西。","جىيەن كۈيئوغۇل ئۆيگە نەرسە يۆتكەشكە ياردەم قىلدى.","jiyen küy'oghul öyge nerse yötkeshke yardem qildi."]],"多孔动物":[["多孔动物属于海洋生物。","كۆپ تۆشۈكلۈك ھايۋانلار دېڭىز بىئولوگىيەسىگە تەۋە.","köp töshüklük haywanlar déngiz biologiyesige tewe."]],"梦乡":[["进入梦乡后，一切烦恼都消失了。","چۈش ئالەمىگە كىرگەندىن كېيىن، بارلىق غەم-قايغۇلار يوقىلىدۇ.","chüsh alemige kirgendin kéyin, barliq ghem-qayghular yoqilidu."]],"大堂":[["大堂的装饰简洁而典雅。","چوڭ زالنىڭ بېزىلىشى ئاددىي ۋە نەپىس.","chong zalning bézilishi addiy we nepis."]],"夜店":[["夜店的音乐节奏感很强。","كېچىلىك كلۇبنىڭ مۇزىكا رېتىمى بەك كۈچلۈك.","kéchilik klubning muzika rétimi bek küchlük."]],"外网":[["外网信息需谨慎。","تاشقى تور ئۇچۇرلىرىغا ئېھتىيات قىلىش كېرەك.","tashqi tor uchurlirigha éhtiyat qilish kérek."]],"大有文章":[["这件事背后大有文章，值得深究。","بۇ ئىشنىڭ ئارقىسىدا چوڭ مەزمۇن بار، چوڭقۇر تەكشۈرۈشكە ئەرزىيدۇ.","bu ishning arqisida chong mezmun bar, chongqur tekshürüshke erziydu."]],"大观":[["大观园是著名景点。","چوڭ كۆرۈنۈش باغچىسى داڭلىق مەنزىرە نۇقتىسىدۇر.","chong körünüsh baghchisi dangliq menzire nuqtisidur."]],"大节":[["大节期间，大家都放假。","چوڭ بايرام مەزگىلىدە ھەممەيلەن دەم ئالىدۇ.","chong bayram mezgilide hemmeylen dem alidu."]],"大丽花":[["大丽花的花色丰富多样。","چوڭ لىخۇا گۈلىنىڭ رەڭلىرى مول ۋە خىلمۇخىل.","chong lixua gülining rengliri mol we xilmuxil."]],"大麦町":[["大麦町的街道非常整洁。","چوڭ مەكلىننىڭ كوچىلىرى ئىنتايىن تازا.","chong meklinning kochiliri intayin taza."]],"天禄":[["天禄是古代的一种官职。","تيەنلۇ قەدىمكى زاماندىكى بىر خىل ئەمەلدارلىق ئورنىدۇر.","tyenlu qedimki zamandiki bir xil emeldarliq ornidur."]],"天津大学":[["天津大学是一所知名高校。","تيەنجىن داشۆسى بىر ئاتاقلىق ئالىي مەكتەپ.","tyenjin dashösi bir ataqliq aliy mektep."]],"天然毒素":[["这种天然毒素对人体有害。","بۇ خىل تەبىئىي زەھەر ئىنسان بەدىنىگە زىيانلىق.","bu xil tebiiy zeher insan bedinige ziyanliq."]],"失和":[["两国因贸易问题陷入失和状态。","ئىككى دۆلەت سودا مەسىلىسى سەۋەبىدىن ئىناقسىزلىق ھالىتىگە چۆمدى.","ikki dölet soda mesilisi sewebidin inaqsizliq halitige chömdi."]],"奉贤":[["奉贤是上海的一个区。","فېڭشيەن شاڭخەيدىكى بىر رايون.","féngshyen shangxeydiki bir rayon."]],"套色":[["印刷时需要调整套色精度。","باسما ۋاقتىدا رەڭ تەڭشەش دەللىكىنى تەڭشەش كېرەك.","basma waqtida reng tengshesh dellikini tengshesh kérek."]],"套曲":[["这套古典套曲令人陶醉。","بۇ كلاسسىك يۈرۈم كۈي ئادەمنى مەست قىلىدۇ.","bu klassik yürüm küy ademni mest qilidu."]],"奥什":[["奥什是吉尔吉斯斯坦的城市。","ئوش قىرغىزىستاننىڭ شەھىرى.","osh qirghizistanning shehiri."]],"好战":[["他是个好战的人。","ئۇ ئۇرۇشقا ئىشتىياقلىق ئادەم.","u urushqa ishtiyaqliq adem."]],"妄生穿凿":[["他妄生穿凿，强行解释历史事件。","ئۇ ئاساسسىز يورۇتۇپ، تارىخىي ۋەقەلەرنى زورلۇق بىلەن چۈشەندۈردى.","u asassiz yorutup, tarixiy weqelerni zorluq bilen chüshendürdi."]],"娄宿":[["娄宿是古代星官名。","لۇشى يۇلتۇزى قەدىمكى زاماندا يۇلتۇز ئورنىنىڭ نامى ئىدى.","lushi yultuzi qedimki zamanda yultuz ornining nami idi."]],"威尔特郡":[["威尔特郡位于英格兰西南部。","ۋىلتشىر شىرئەسى ئەنگلىيەنىڭ جەنۇبىي غەربىدە جايلاشقان.","wiltshir shir'esi engliyening jenubiy gherbide jaylashqan."]],"威远":[["威远是一个历史悠久的地方。","ۋېييۈەن ئۇزۇن تارىخقا ئىگە بىر جاي.","wéyyüen uzun tarixqa ige bir jay."]],"威卜":[["威卜是个勇敢的人。","ۋېيبۇ باتۇر بىر ئادەم.","wéybu batur bir adem."]],"委员长":[["委员长主持会议议程。","كومىتېت رەئىسى يىغىن كۈنتەرتىپىگە رىياسەتچىلىك قىلدى.","komitét reisi yighin küntertipige riyasetchilik qildi."]],"孔雀座":[["孔雀座是南天星座。","توزغۇن يۇلتۇزلار تۈركۈمى جەنۇبىي ئاسماندىكى يۇلتۇزلار تۈركۈمى.","tozghun yultuzlar türkümi jenubiy asmandiki yultuzlar türkümi."]],"字串":[["这个字串包含多个字符。","بۇ ھەرپ تىزمىسى بىر قانچە ھەرپنى ئۆز ئىچىگە ئالىدۇ.","bu herp tizmisi bir qanche herpni öz ichige alidu."]],"子宫颈抹片":[["子宫颈抹片用于筛查癌症。","بالىياتقۇ ئېغىزى سۈرتۈندىسى راك كېسەللىكىنى ئەلەشكە ئىشلىتىلىدۇ.","baliyatqu éghizi sürtündisi rak késellikini eleshke ishlitilidu."]],"孤注一掷":[["他孤注一掷，赌上了全部家产。","ئۇ بارلىق مۈلكىنى تىكىپ، يالغۇز بىر تەۋەككۈل قىلدى.","u barliq mülkini tikip, yalghuz bir tewekkül qildi."]],"孤立无援":[["他孤立无援，只能等待救援。","ئۇ يالغۇز ۋە ياردەمسىز، پەقەت قۇتقۇزۇشنى كۈتەلەيدۇ.","u yalghuz we yardemsiz, peqet qutquzushni küteleydu."]],"孤证不立":[["孤证不立，需要更多证据支持。","يالغۇز ئىسپات بىلەن ئىش پۈتمەيدۇ، تېخىمۇ كۆپ ئىسپاتنىڭ قوللىشى كېرەك.","yalghuz ispat bilen ish pütmeydu, téximu köp ispatning qollishi kérek."]],"守恒定律":[["能量守恒定律是物理学的基础。","ئېنېرگىيە ساقلىنىش قانۇنى فىزىكىنىڭ ئاساسىدۇر.","énérgiye saqlinish qanuni fizikining asasidur."]],"孤鸟":[["那只孤鸟在枝头独自鸣叫。","ئۇ يالغۇز قۇش شاخ ئۈستىدە يالغۇز ئۆزى سايرايدۇ.","u yalghuz qush shax üstide yalghuz özi sayraydu."]],"孙吴":[["孙吴是三国时期的政权之一。","سۈن ۋۇ ئۈچ پادىشاھلىق دەۋرىدىكى ھاكىمىيەتلەرنىڭ بىرى.","sün wu üch padishahliq dewridiki hakimiyetlerning biri."]],"宋书":[["《宋书》是记载南朝宋代历史的史书。","«سۇڭ كىتابى» جەنۇبىي سۇلالىلەر دەۋرىدىكى سۇڭ سۇلالىسى تارىخىنى خاتىرىلىگەن تارىخىي كىتاب.","«sung kitabi» jenubiy sulaliler dewridiki sung sulalisi tarixini xatiriligen tarixiy kitab."]],"宣礼塔":[["宣礼塔是清真寺的重要建筑。","ئەزان مۇنارى مەسچىتنىڭ مۇھىم بىناسى.","ezan munari meschitning muhim binasi."]],"家谱":[["家谱记录了家族的历史渊源。","ئائىلە شەجەرىسى ئائىلىنىڭ تارىخىي كېلىپ چىقىشىنى خاتىرىلەيدۇ.","aile shejerisi ailining tarixiy kélip chiqishini xatirileydu."]],"实则":[["实则情况不同。","ئەمەلىيەتتە ئەھۋال باشقىچە ئىدى.","emeliyette ehwal bashqiche idi."]],"密送":[["情报被秘密送往总部。","ئۇچۇرلار مەخپىي ھالدا باش شتابقا ئەۋەتىلدى.","uchurlar mexpiy halda bash shtabqa ewetildi."]],"宁津县":[["宁津县历史悠久，文化丰富。","نىڭجىن ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى مول.","ningjin nahiyisining tarixi uzun, medeniyiti mol."]],"宁远":[["宁远是湖南省的一个县。","نىڭيۈەن خۇنەن ئۆلكىسىنىڭ بىر ناھىيىسى.","ningyüen xunen ölkisining bir nahiyisi."]],"富阳市":[["富阳市是浙江省的一座地级市。","فۇياڭ شەھىرى جېجياڭ ئۆلكىسىنىڭ بىر ۋىلايەت دەرىجىلىك شەھىرى.","fuyang shehiri jéjyang ölkisining bir wilayet derijilik shehiri."]],"宽弘":[["他为人宽弘，从不计较。","ئۇ كەڭ قورساق، ھەرگىز كىچىك ئىشلارغا پەرۋا قىلمايدۇ.","u keng qorsaq, hergiz kichik ishlargha perwa qilmaydu."]],"宝典":[["这本宝典包含实用技巧。","بۇ خەزىنە قوللانمىسى ئەمەلىي ماھارەتلەرنى ئۆز ئىچىگە ئالىدۇ.","bu xezine qollanmisi emeliy maharetlerni öz ichige alidu."]],"实际应用":[["理论需要实际应用。","نەزەرىيە ئەمەلىي قوللىنىشقا موھتاج.","nezeriye emeliy qollinishqa mohtaj."]],"富源县":[["富源县盛产优质煤炭。","فۇيۈەن ناھىيەسى سۈپەتلىك كۆمۈرگە باي.","fuyüen nahiyesi süpetlik kömürge bay."]],"寒舍":[["欢迎光临寒舍，请随意走动。","سەمىمىي ئۆيىمىزگە خۇش كەلدىڭىز، خالىغانچە يۈرۈڭ.","semimiy öyimizge xush keldingiz, xalighanche yürüng."]],"寸步不离":[["孩子生病时，他寸步不离地守在床边。","بالىسى كېسەل بولغاندا، ئۇ كارىۋات بېشىدىن قىلچە ئايرىلماي ساقلايدۇ.","balisi késel bolghanda, u kariwat béshidin qilche ayrilmay saqlaydu."]],"寸步难行":[["暴雨过后，道路泥泞，寸步难行。","قويۇن يامغۇردىن كېيىن، يول لاي بولۇپ، قەدەم تاشلاش تەس بولۇپ قالدى.","qoyun yamghurdin kéyin, yol lay bolup, qedem tashlash tes bolup qaldi."]],"寻欢作乐":[["年轻人喜欢寻欢作乐。","ياشلار كۆڭۈل ئېچىشنى ياخشى كۆرىدۇ.","yashlar köngül échishni yaxshi köridu."]],"对答":[["他回答问题对答如流。","ئۇ سوئالغا جاۋاب بېرىشتە سۇدەك ئاقتى.","u soalgha jawab bérishte sudek aqti."]],"小型货车":[["物流公司用小型货车送货。","لوگىستىكا شىركىتى كىچىك تىپتىكى يۈك ماشىنىسى بىلەن مال يەتكۈزىدۇ.","logistika shirkiti kichik tiptiki yük mashinisi bilen mal yetküzidu."]],"小洞不堵，大洞受苦":[["小洞不堵，大洞受苦。","كىچىك تۆشۈك توسۇلمىسا، چوڭ تۆشۈك ئازاب چېكىدۇ.","kichik töshük tosulmisa, chong töshük azab chékidu."]],"尤诟":[["作品常遭人尤诟。","ئەسەرلەر كۆپىنچە كىشىلەر تەرىپىدىن ئەيىبلىنىدۇ.","eserler köpinche kishiler teripidin eyiblinidu."]],"尼康":[["尼康是一家知名的相机品牌。","نىكون تونۇلغان بىر كامېرا ماركىسىدۇر.","nikon tonulghan bir kaméra markisidur."]],"小溪":[["清澈的小溪在山间流淌。","سۈزۈك كىچىك ئېقىن تاغلار ئارىسىدا ئېقىپ تۇرىدۇ.","süzük kichik éqin taghlar arisida éqip turidu."]],"屎蚵螂":[["这种昆虫被称为屎蚵螂。","بۇ خىل ھاشارات تەرەت قوڭغۇزى دەپ ئاتىلىدۇ.","bu xil hasharat teret qongghuzi dep atilidu."]],"展台":[["展台上摆放着精美的展品。","كۆرگەزمە سۇپىسىدا نەپىس كۆرگەزمە بۇيۇملىرى قويۇلغان.","körgezme supisida nepis körgezme buyumliri qoyulghan."]],"山行":[["山行需要准备充足的饮用水和食物。","تاغدا مېڭىشتا يېتەرلىك ئىچىملىك سۇ ۋە يېمەكلىك تەييارلاش كېرەك.","taghda méngishta yéterlik ichimlik su we yémeklik teyyarlash kérek."]],"山歌":[["山歌是山区的传统民歌。","شاڭگە تاغلىق رايونلارنىڭ ئەنئەنىۋى خەلق ناخشىسىدۇر.","shangge taghliq rayonlarning en'eniwi xelq naxshisidur."]],"山羌":[["山羌是一种小型的哺乳动物。","شاڭچياڭ كىچىك تىپتىكى سۈت ئەمگۈچى ھايۋاندۇر.","shangchyang kichik tiptiki süt emgüchi haywandur."]],"岩径":[["岩径是登山者常用的路线。","تاش يول تاغكەشلەر كۆپ ئىشلىتىدىغان يول.","tash yol taghkeshler köp ishlitidighan yol."]],"崖壑":[["崖壑深不见底。","يار ئېتىكىنىڭ ئاستى كۆرۈنمەيدۇ.","yar étikining asti körünmeydu."]],"巡礼":[["信徒前往圣地进行虔诚的巡礼。","مۆئمىنلەر مۇقەددەس جايغا چىن دىلىدىن شۈنلى قىلغىلى بارىدۇ.","möminler muqeddes jaygha chin dilidin shünli qilghili baridu."]],"巍山县":[["巍山县以独特的自然风光著称。","ۋېيشەن ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","wéyshen nahiyisi özgiche tebiiy menzirisi bilen dangliq."]],"巍然屹立":[["这座古塔巍然屹立，历经千年不倒。","بۇ قەدىمىي مۇنار ھەيۋەت بىلەن تىك تۇرۇپ، مىڭ يىل ئۆتسىمۇ يىقىلمىدى.","bu qedimiy munar heywet bilen tik turup, ming yil ötsimu yiqilmidi."]],"已灭":[["这座古城早已已灭。","بۇ قەدىمىي شەھەر ئاللىبۇرۇن يوقىلىپ كەتكەن.","bu qedimiy sheher alliburun yoqilip ketken."]],"巨大影响":[["这项政策产生了巨大影响。","بۇ سىياسەت زور تەسىر پەيدا قىلدى.","bu siyaset zor tesir peyda qildi."]],"巴斯":[["巴斯是英格兰的一个著名城市。","بات ئېنگلاندىيەنىڭ مەشھۇر بىر شەھىرى.","bat énglandiyening meshhur bir shehiri."]],"帕提亚人":[["帕提亚人是古代中东的一个民族。","پارتىيەلار قەدىمكى ئوتتۇرا شەرقنىڭ بىر مىللىتى ئىدى.","partiyelar qedimki ottura sherqning bir milliti idi."]],"帕尔瓦蒂":[["帕尔瓦蒂是印度教的重要女神。","پارۋاتى ھىندۇ دىنىنىڭ مۇھىم بىر ئىلاھىسىدۇر.","parwati hindu dinining muhim bir ilahisidur."]],"平南县":[["平南县以优质的甘蔗种植著称。","پىڭنەن ناھىيىسى سۈپەتلىك شېكەر قومۇشى ئۆستۈرۈش بىلەن تونۇلغان.","pingnen nahiyisi süpetlik shéker qomushi östürüsh bilen tonulghan."]],"平明":[["平明之际，太阳从东方缓缓升起。","تاڭ ئاتقاندا، قۇياش شەرقتىن ئاستا كۆتۈرۈلدى.","tang atqanda, quyash sherqtin asta kötürüldi."]],"平板手机":[["平板手机结合了手机和平板的功能，便于携带。","تەكشى تاختىلىق تېلېفون تېلېفون بىلەن تەكشى تاختىنىڭ ئىقتىدارىنى بىرلەشتۈرگەن، ئېلىپ يۈرۈشكە قولايلىق.","tekshi taxtiliq téléfon téléfon bilen tekshi taxtining iqtidarini birleshtürgen, élip yürüshke qolayliq."]],"底数":[["底数计算正确。","ئاستى سان ھېسابلاش توغرا.","asti san hésablash toghra."]],"平型关":[["平型关是历史上的重要战役地。","پىڭشىڭگۇان تارىختىكى مۇھىم جەڭ مەيدانى.","pingshingguan tarixtiki muhim jeng meydani."]],"平城":[["平城是古代的重要都城。","پىڭچېڭ قەدىمكى دەۋردىكى مۇھىم پايتەخت ئىدى.","pingchéng qedimki dewrdiki muhim paytext idi."]],"库肯霍夫公园":[["库肯霍夫公园的花海令人惊叹。","كۇكنخوف باغچىسىنىڭ گۈل دېڭىزى كىشىنى ھەيران قالدۇرىدۇ.","kuknxof baghchisining gül déngizi kishini heyran qalduridu."]],"幻化":[["他瞬间幻化出各种形态。","ئۇ بىر مەزگىلدە تۈرلۈك شەكىللەرگە خىيالىي ئايلاندى.","u bir mezgilde türlük shekillerge xiyaliy aylandi."]],"座堂":[["这座堂建筑是当地的标志性景点。","بۇ تالا بىناسى يەرلىك ئالاھىدە مەنزىرە نۇقتىسىدۇر.","bu tala binasi yerlik alahide menzire nuqtisidur."]],"康拜因":[["康拜因是联合收割机。","كومباين بىرلەشمە ئورغاق ماشىنىسى.","kombayn birleshme orghaq mashinisi."]],"废人":[["他因事故成了废人。","ئۇ ھادىسە سەۋەبىدىن يارامسىز ئادەم بولۇپ قالدى.","u hadise sewebidin yaramsiz adem bolup qaldi."]],"广博":[["这家博物馆收藏非常广博。","بۇ مۇزېينىڭ توپلىمى ئىنتايىن كەڭ.","bu muzéyning toplimi intayin keng."]],"广告商":[["广告商需要精准定位目标受众。","ئېلان سودىگىرى نىشانلىق ئاڭلىغۇچىلارنى ئېنىق بەلگىلىشى كېرەك.","élan sodigiri nishanliq anglighuchilarni éniq belgilishi kérek."]],"广砚":[["广砚是一种珍贵的文房用品。","گۇاڭيەن قىممەتلىك يازما-ئەسۋابىدۇر.","guangyen qimmetlik yazma-eswabidur."]],"广电总局":[["国家广电总局监管全国广播电视。","دۆلەت رادىئو-تېلېۋىزىيە باش ئىدارىسى پۈتۈن مەملىكەتتىكى رادىئو-تېلېۋىزىيەنى نازارەت قىلىدۇ.","dölet radio-téléwiziye bash idarisi pütün memlikettiki radio-téléwiziyeni nazaret qilidu."]],"弗莱福兰":[["弗莱福兰是荷兰的农业大省。","فلېۋولاند نىدېرلاندىيەنىڭ يېزا ئىگىلىك چوڭ ئۆلكىسى.","fléwoland nidérlandiyening yéza igilik chong ölkisi."]],"引述":[["请正确引述他人的观点。","باشقىلارنىڭ كۆز قارىشىنى توغرا نەقىل قىلىڭ.","bashqilarning köz qarishini toghra neqil qiling."]],"张弛":[["张弛在音乐创作中展现了独特的风格。","جاڭ چى مۇزىكا ئىجادىيىتىدە ئۆزگىچە ئۇسلۇبىنى نامايان قىلدى.","jang chi muzika ijadiyitide özgiche uslubini namayan qildi."]],"影印机":[["影印机坏了需要维修。","سۈرەت كۆپەيتىش ماشىنىسى بۇزۇلۇپ رېمونت قىلىش كېرەك.","süret köpeytish mashinisi buzulup rémont qilish kérek."]],"后凉":[["后凉政权最终被消灭。","ئاخىرقى لياڭ ھاكىمىيىتى ئاخىرىدا يوقىتىلدى.","axirqi lyang hakimiyiti axirida yoqitildi."]],"后汉":[["后汉时期经济逐渐复苏。","ئاخىرقى خەن دەۋرىدە ئىقتىساد تەدرىجىي ئەسلىگە كەلدى.","axirqi xen dewride iqtisad tedrijiy eslige keldi."]],"弹孔":[["弹孔的边缘有些毛糙。","ئوق تەسىسىنىڭ گىرۋىكى بىر ئاز يىرىڭقى.","oq tesisining girwiki bir az yiringqi."]],"得色":[["他因成功而满脸得色。","ئۇ مۇۋەپپەقىيەتتىن كۆرۈنەرلىك پەخىرلەندى.","u muweppeqiyettin körünerlik pexirlendi."]],"徐克":[["徐克是一位著名的导演和制片人。","شۈ كې داڭلىق رېژىسسور ۋە پرودۇسېر.","shü ké dangliq rézhissor we produsér."]],"徐继畲":[["徐继畲是清代著名的外交家。","شۈ جىشې چىڭ سۇلالىسى دەۋرىنىڭ داڭلىق دىپلوماتى.","shü jishé ching sulalisi dewrining dangliq diplomati."]],"循规蹈矩":[["他始终循规蹈矩，从不越界。","ئۇ ھەمىشە قائىدە-يوسۇنغا بويسۇنۇپ، ھەرگىز چەكتىن ئاشمايدۇ.","u hemishe qaide-yosungha boysunup, hergiz chektin ashmaydu."]],"微缩":[["微缩模型展现了古代城市的布局。","مىكرو كىچىكلىتىلگەن مودېل قەدىمكى شەھەرنىڭ ئورۇنلاشتۇرۇلۇشىنى نامايان قىلدى.","mikro kichiklitilgen modél qedimki sheherning orunlashturulushini namayan qildi."]],"德克萨斯":[["德克萨斯州以牛仔文化闻名。","تېكساس شىتاتى كابوي مەدەنىيىتى بىلەن داڭلىق.","téksas shitati kaboy medeniyiti bilen dangliq."]],"恒山区":[["恒山区是哈尔滨的一个区。","خېڭشەن رايونى خارۋىن شەھىرىنىڭ بىر رايونىدۇر.","xéngshen rayoni xarwin shehirining bir rayonidur."]],"恩将仇报":[["他竟恩将仇报，背叛了多年的朋友。","ئۇ ئەجەبا مەرھەمەتكە يامانلىق قايتۇرۇپ، كۆپ يىللىق دوستىغا خىيانەت قىلدى.","u ejeba merhemetke yamanliq qayturup, köp yilliq dostigha xiyanet qildi."]],"恩眄":[["君主的恩眄，足以改变命运。","پادىشاھنىڭ مەرھەمەتلىك نەزىرى تەقدىرنى ئۆزگەرتىشكە يېتەرلىكتۇر.","padishahning merhemetlik neziri teqdirni özgertishke yéterliktur."]],"心神":[["心神不宁的人难以集中注意力完成工作。","روھى بىئارام كىشىلەر دىققىتىنى مەركەزلەشتۈرۈپ خىزمەتنى تاماملىشى قىيىن.","rohi biaram kishiler diqqitini merkezleshtürüp xizmetni tamamlishi qiyin."]],"患难":[["他们一起经历了患难。","ئۇلار بىرلىكتە جاپا-مۇشەققەتنى باشتىن كەچۈردى.","ular birlikte japa-musheqqetni bashtin kechürdi."]],"闷酒":[["他独自闷酒，沉默不语。","ئۇ يالغۇز پىسە ھاراق ئىچتى، ئۈنسىز قالدى.","u yalghuz pise haraq ichti, ünsiz qaldi."]],"恬愉之安":[["恬愉之安是一种内心的平静。","تىنچ-خاتىرجەملىك بىر خىل ئىچكى خاتىرجەملىكتۇر.","tinch-xatirjemlik bir xil ichki xatirjemliktur."]],"恬谧":[["夜晚的村庄格外恬谧。","كېچىدە كەنت ئالاھىدە جىمجىت.","kéchide kent alahide jimjit."]],"急着":[["他急着出门，连衣服都没穿好。","ئۇ ئالدىراپ سىرتقا چىقماقچى بولۇپ، كىيىمىنىمۇ تولۇق كىيەلمىدى.","u aldirap sirtqa chiqmaqchi bolup, kiyiminimu toluq kiyelmidi."]],"悔意":[["他的悔意溢于言表，令人动容。","ئۇنىڭ پۇشايمانى سۆزلىرىدىن بىلىنىپ، كىشىنى ھەسرەتكە سالدى.","uning pushaymani sözliridin bilinip, kishini hesretke saldi."]],"悟空":[["孙悟空也叫作悟空。","سۈن ۋۇكۇڭ يەنە ۋۇكۇڭ دەپمۇ ئاتىلىدۇ.","sün wukung yene wukung depmu atilidu."]],"意大利青瓜":[["意大利青瓜清爽可口。","ئىتالىيە كۆكى قوغۇنچىسى تازا ۋە تەملىك.","italiye köki qoghunchisi taza we temlik."]],"感人":[["这个故事非常感人。","بۇ ھېكايە ئىنتايىن تەسىرلىك.","bu hékaye intayin tesirlik."]],"成型":[["模型已经初步成型。","مودېل ئاللىبۇرۇن دەسلەپكى شەكىلگە كىردى.","modél alliburun deslepki shekilge kirdi."]],"戊寅":[["戊寅年属于木元素的年份。","پېنتا يىلى ياغاچ ئۇنسۇرىغا تەۋە يىل.","pénta yili yaghach unsurigha tewe yil."]],"戊戌政变":[["戊戌政变标志着改革的失败。","پېنتاۋ سىياسىي ئۆزگىرىشى ئىسلاھاتنىڭ مەغلۇبىيىتىنى كۆرسەتتى.","péntaw siyasiy özgirishi islahatning meghlubiyitini körsetti."]],"应用软件":[["公司推出了多款实用的应用软件。","شىركەت كۆپ خىل ئەمەلىي ئەپ يۇمشاق دېتاللىرىنى تەقلىم قىلدى.","shirket köp xil emeliy ep yumshaq détallirini teqlim qildi."]],"应诏":[["官员应诏入宫，参与重要决策。","ئەمەلدارلار پادىشاھنىڭ بۇيرۇقى بويىچە سارايغا كىرىپ، مۇھىم قارارلارغا قاتنىشىدۇ.","emeldarlar padishahning buyruqi boyiche saraygha kirip, muhim qararlargha qatnishidu."]],"所闻":[["他所说的所闻令人难以置信。","ئۇنىڭ ئاڭلىغانلىرى ئىشەنگۈسىز ئىشلاردۇر.","uning anglighanliri ishengüsiz ishlardur."]],"扇形":[["这个扇形图案装饰在窗帘上。","بۇ يەلپۈگۈچسىمان نەقىش پەردىگە بېزەلگەن.","bu yelpügüchsiman neqish perdige bézelgen."]],"才貌双全":[["她不仅貌美，而且才貌双全。","ئۇ پەقەت گۈزەللا ئەمەس، بەلكى ھۆسۈن ۋە تالانتقا تەڭ ئىگە.","u peqet güzella emes, belki hösün we talantqa teng ige."]],"打炮":[["他们讨论如何打炮庆祝。","ئۇلار توپ ئېتىپ تەبرىكلەش ئۇسۇلىنى مۇزاكىرە قىلدى.","ular top étip tebriklesh usulini muzakire qildi."]],"手书":[["这幅手书展现了作者的书法功底。","بۇ قولدا يېزىلغان ئەسەر ئاپتورنىڭ خەتتاتلىق ئاساسىنى نامايان قىلدى.","bu qolda yézilghan eser aptorning xettatliq asasini namayan qildi."]],"打问":[["他打问起昨天的事。","ئۇ تۈنۈگۈنكى ئىش توغرىسىدا سوراپ بىلدى.","u tünügünki ish toghrisida sorap bildi."]],"打垮":[["他打垮了敌人的防线。","ئۇ دۈشمەننىڭ مۇداپىئە سېپىنى بۇزۇپ تاشلىدى.","u düshmenning mudapie sépini buzup tashlidi."]],"扶危":[["他扶危济困，乐于助人。","ئۇ خەتەرگە يولۇققانلارغا ياردەم قىلىپ، ياردەمگە ئېھتىياجلىق ئادەملەرنى خۇشال قىلىدۇ.","u xeterge yoluqqanlargha yardem qilip, yardemge éhtiyajliq ademlerni xushal qilidu."]],"成事":[["他善于成事，总能解决问题。","ئۇ ئىشلارنى ئوڭۇشلۇق بىتىرىشكە ماھىر، ھەمىشە مەسىلىلەرنى ھەل قىلالايدۇ.","u ishlarni ongushluq bitirishke mahir, hemishe mesililerni hel qilalaydu."]],"成例":[["这个案例已成为行业内的成例。","بۇ ئىش ھازىر ساھە ئىچىدىكى ئۈلگە بولۇپ قالدى.","bu ish hazir sahe ichidiki ülge bolup qaldi."]],"批处理":[["系统会自动进行批处理操作。","سىستېما ئاپتوماتىك ھالدا تۈركۈملەپ بىر تەرەپ قىلىش مەشغۇلاتىنى ئېلىپ بارىدۇ.","sistéma aptomatik halda türkümlep bir terep qilish meshghulatini élip baridu."]],"拉伸强度":[["拉伸强度与材料性能密切相关。","سوزۇش كۈچى ماتېرىيال ئىقتىدارى بىلەن زىچ مۇناسىۋەتلىك.","sozush küchi matériyal iqtidari bilen zich munasiwetlik."]],"拉伤":[["运动不当容易拉伤肌肉。","ھەرىكەت خاتا بولسا مۇسكۇل سوزۇلۇپ زەخىملىنىش ئاسان.","heriket xata bolsa muskul sozulup zeximlinish asan."]],"拙朴":[["这幅画风格拙朴自然。","بۇ رەسىمنىڭ ئۇسلۇبى ساددە ۋە تەبىئىي.","bu resimning uslubi sadde we tebiiy."]],"拙直":[["他性格拙直，不圆滑。","ئۇنىڭ خاراكتېرى توغرا، ئىككى يۈزلۈك ئەمەس.","uning xaraktéri toghra, ikki yüzlük emes."]],"招架":[["他努力招架。","ئۇ قارشىلىق كۆرسىتىشكە تىرىشتى.","u qarshiliq körsitishke tirishti."]],"括弧":[["请用括弧把公式里的变量圈起来。","فورمۇلادىكى ئۆزگەرگۈچىلەرنى قوشۇمچە قىسقۇچ بىلەن ئوراپ قويۇڭ.","formuladiki özgergüchilerni qoshumche qisquch bilen orap qoyung."]],"拯救大兵瑞恩":[["《拯救大兵瑞恩》是一部经典的战争片。","«راياننى قۇتقۇزۇش» كلاسسىك ئۇرۇش فىلىمى.","«rayanni qutquzush» klassik urush filimi."]],"指南宫":[["指南宫是古代建筑。","جىنەنگۇڭ ئوردىسى قەدىمكى بىنا.","jinengung ordisi qedimki bina."]],"指数套利":[["指数套利利用市场差异获利。","كۆرسەتكۈچ ئاربتىراژى بازار پەرقىدىن پايدىلىنىپ پايدا ئالىدۇ.","körsetküch arbtirazhi bazar perqidin paydilinip payda alidu."]],"拿骚":[["拿骚是巴哈马的首都。","ناسساۋ باھامانىڭ پايتەختى.","nassaw bahamaning paytexti."]],"扫视":[["他扫视了全场观众。","ئۇ پۈتۈن مەيداندىكى تاماشىبىنلارغا كۆز يۈگۈرتتى.","u pütün meydandiki tamashibinlargha köz yügürtti."]],"探究式":[["这种探究式学习能激发创造力。","بۇ خىل ئىزدىنىش خاراكتېرلىك ئۆگىنىش ئىجادىيەت كۈچىنى قوزغايدۇ.","bu xil izdinish xaraktérlik öginish ijadiyet küchini qozghaydu."]],"扬子江":[["长江又称扬子江，是中国最长的河流。","ئۇزۇن دەريا يەنە يانگتسى دەرياسى دەپمۇ ئاتىلىپ، جۇڭگونىڭ ئەڭ ئۇزۇن دەرياسى ھېسابلىنىدۇ.","uzun derya yene yangtsi deryasi depmu atilip, junggoning eng uzun deryasi hésablinidu."]],"损人":[["他的话常常损人。","ئۇنىڭ سۆزلىرى دائىم باشقىلارنىڭ كۆڭلىنى ئاغرىتىدۇ.","uning sözliri daim bashqilarning könglini aghritidu."]],"搜狗":[["使用搜狗输入法打字。","سوگۇ كىرگۈزۈش ئۇسۇلىنى ئىشلىتىپ خەت بېسىڭ.","sogu kirgüzüsh usulini ishlitip xet bésing."]],"搜罗":[["他搜罗了许多古董收藏。","ئۇ نۇرغۇن قەدىمكى ئەسەرلەرنى ئىزدەپ توپلىدى.","u nurghun qedimki eserlerni izdep toplidi."]],"挖坑":[["他们挖坑种树，准备绿化环境。","ئۇلار ئورەك قېزىپ دەرەخ تىكتى، مۇھىتنى يېشىللىق بىلەن قاپلاشقا تەييارلىق قىلدى.","ular orek qézip derex tikti, muhitni yéshilliq bilen qaplashqa teyyarliq qildi."]],"搞错":[["他搞错了号码。","ئۇ نومۇرنى خاتا يازدى.","u nomurni xata yazdi."]],"撒种":[["春天是撒种的好季节。","باھار ئۇرۇق چېچىشنىڭ ياخشى پەسلى.","bahar uruq chéchishning yaxshi pesli."]],"摈弃":[["她摈弃了旧观念。","ئۇ كونا چۈشەنچىلەرنى تاشلىدى.","u kona chüshenchilerni tashlidi."]],"拨正":[["他拨正了偏离的方向。","ئۇ چەتنەپ كەتكەن يۆنىلىشنى تۈزەتتى.","u chetnep ketken yönilishni tüzetti."]],"据险":[["据险而建，这座堡垒异常坚固。","خەتەرلىك جايغا تايىنىپ قۇرۇلغان بۇ قەلئە ئىنتايىن مۇستەھكەم.","xeterlik jaygha tayinip qurulghan bu qel'e intayin mustehkem."]],"支公司":[["这家公司的支公司设在上海。","بۇ شىركەتنىڭ تارماق شىركىتى شاڭخەيدە قۇرۇلغان.","bu shirketning tarmaq shirkiti shangxeyde qurulghan."]],"收山":[["他决定收山，不再从事这行。","ئۇ بۇ كەسىپنى تاشلاشقا قارار قىلدى.","u bu kesipni tashlashqa qarar qildi."]],"攻击力":[["这款武器攻击力极强。","بۇ قورالنىڭ ھۇجۇم كۈچى ئىنتايىن كۈچلۈك.","bu qoralning hujum küchi intayin küchlük."]],"政府债券":[["政府债券是重要的融资工具。","ھۆكۈمەت ئوبلىگاتسىيىسى مۇھىم مەبلەغ توپلاش قورالى.","hökümet obligatsiyisi muhim meblegh toplash qorali."]],"教头":[["教头指导弟子练习武术技巧。","مەشىق ئۇستازى شاگىرتلارغا ھەربىي سەنئەت ماھارىتىنى مەشىق قىلدۇرىدۇ.","meshiq ustazi shagirtlargha herbiy sen'et maharitini meshiq qilduridu."]],"敌众我寡":[["敌众我寡，形势危急。","دۈشمەن كۆپ، بىز ئاز، ئەھۋال جىددىي.","düshmen köp, biz az, ehwal jiddiy."]],"敷衍了事":[["他敷衍了事，没认真工作。","ئۇ ئىشنى ئۈستى-ئۈستى قىلىپ، جىددىي ئىشلىمىدى.","u ishni üsti-üsti qilip, jiddiy ishlimidi."]],"敷衍塞责":[["这种态度是敷衍塞责。","بۇنداق پوزىتسىيە مەسئۇلىيەتسىزلىكتۇر.","bundaq pozitsiye mes'uliyetsizliktur."]],"整环":[["数学中的整环有特定定义。","ماتېماتىكىدىكى پۈتۈن ھالقىنىڭ ئالاھىدە ئېنىقلىمىسى بار.","matématikidiki pütün halqining alahide éniqlimisi bar."]],"斑颈穗鹛":[["斑颈穗鹛的颈部有独特的斑纹。","تاغ تېكىسى بوينى باشاقلىق قۇشىنىڭ بويۇنىدا ئالاھىدە تاغ تېكىسى بار.","tagh tékisi boyni bashaqliq qushining boyunida alahide tagh tékisi bar."]],"斑马":[["草原上的斑马成群结队地奔跑。","يايلاقتىكى تاغ تېكىسى ئات توپ-توپ بولۇپ يۈگۈرىدۇ.","yaylaqtiki tagh tékisi at top-top bolup yügüridu."]],"料头":[["这道菜的料头需要提前准备好。","بۇ تائامنىڭ ماتېرىيال بېشىنى ئالدىن تەييارلاش كېرەك.","bu taamning matériyal béshini aldin teyyarlash kérek."]],"斥退":[["领导斥退了表现不佳的员工。","رەھبەر ئىقتىدارى ناچار خىزمەتچىنى قوغلاپ چىقاردى.","rehber iqtidari nachar xizmetchini qoghlap chiqardi."]],"斧钺汤镬":[["斧钺汤镬是古代酷刑的代称。","پالتا ۋە قازان ئازابى قەدىمكى زاماندىكى قاتتىق جازالارنىڭ ئورۇن باسارى.","palta we qazan azabi qedimki zamandiki qattiq jazalarning orun basari."]],"新北市":[["新北市是台湾人口最多的城市之一。","يېڭىبېي شەھىرى تەيۋەندە نوپۇسى ئەڭ كۆپ شەھەرلەرنىڭ بىرى.","yéngibéy shehiri teywende nopusi eng köp sheherlerning biri."]],"新店市":[["新店市是著名的旅游城市。","يېڭىدىيەن شەھىرى مەشھۇر ساياھەت شەھىرى.","yéngidiyen shehiri meshhur sayahet shehiri."]],"整流器":[["整流器将交流电转为直流。","تۈزلىگۈچ ئۆزگەرمە ئېلېكتر ئېقىمىنى تۇراقلىق ئېلېكتر ئېقىمىغا ئايلاندۇرىدۇ.","tüzligüch özgerme éléktr éqimini turaqliq éléktr éqimigha aylanduridu."]],"断舍离":[["断舍离倡导极简生活方式。","ئۈزۈش-تاشلاش ئاددىي تۇرمۇش ئۇسۇلىنى تەشەببۇس قىلىدۇ.","üzüsh-tashlash addiy turmush usulini teshebbus qilidu."]],"断案":[["断案需要严谨的推理。","دەۋا ھەل قىلىش ئېنىق پەرەز قىلىشنى تەلەپ قىلىدۇ.","dewa hel qilish éniq perez qilishni telep qilidu."]],"新闻学":[["新闻学是研究信息传播的学科。","خەۋەرشۇناسلىق ئۇچۇر تارقىتىشنى تەتقىق قىلىدىغان پەن.","xewershunasliq uchur tarqitishni tetqiq qilidighan pen."]],"既视感":[["看这部电影时，我产生了强烈的既视感。","بۇ فىلىمنى كۆرگەندە مەندە كۈچلۈك ئاللىبۇرۇن كۆرگەندەك تۇيغۇ پەيدا بولدى.","bu filimni körgende mende küchlük alliburun körgendek tuyghu peyda boldi."]],"旨趣":[["这幅画的旨趣在于自然。","بۇ رەسىمنىڭ مەقسىتى تەبىئەتتە.","bu resimning meqsiti tebiette."]],"易损性":[["这个材料有易损性。","بۇ ماتېرىيالنىڭ ئاسان بۇزۇلۇش خۇسۇسىيىتى بار.","bu matériyalning asan buzulush xususiyiti bar."]],"明光":[["明光是一种古老的照明工具。","مىڭگۇاڭ قەدىمىي بىر يورۇتۇش قورالى.","mingguang qedimiy bir yorutush qorali."]],"明枪易躲，暗箭难防":[["明枪易躲，暗箭难防，须小心应对。","ئوچۇق ئوقتىن ساقلىنىش ئاسان، يوشۇرۇن ئوقتىن ساقلىنىش تەس، ئېھتىيات قىلىش كېرەك.","ochuq oqtin saqlinish asan, yoshurun oqtin saqlinish tes, éhtiyat qilish kérek."]],"星期四":[["星期四会议结束后，大家讨论了下周的工作安排。","پەيشەنبە كۈنى يىغىن ئاخىرلاشقاندىن كېيىن، ھەممەيلەن كېلەر ھەپتىنىڭ خىزمەت ئورۇنلاشتۇرۇشى توغرىسىدا مۇزاكىرە قىلدى.","peyshenbe küni yighin axirlashqandin kéyin, hemmeylen kéler heptining xizmet orunlashturushi toghrisida muzakire qildi."]],"晋书":[["《晋书》是记载晋朝历史的史书。","«جىن شۇ» جىن سۇلالىسىنىڭ تارىخىنى خاتىرىلەيدىغان تارىخىي كىتابتۇر.","«jin shu» jin sulalisining tarixini xatirileydighan tarixiy kitabtur."]],"时装表演":[["模特在舞台上展示时装表演。","مودېل سەھنىدە مودا كىيىم كۆرگەزمىسىنى نامايان قىلدى.","modél sehnide moda kiyim körgezmisini namayan qildi."]],"时运不济":[["他最近时运不济，诸事不顺。","ئۇ يېقىندا تەلەيى يار بولماي، ھەممە ئىشى ئوڭۇشسىز بولدى.","u yéqinda teleyi yar bolmay, hemme ishi ongushsiz boldi."]],"普利策奖":[["他凭借作品获得了普利策奖。","ئۇ ئەسىرى بىلەن پۇلىتسېر مۇكاپاتىغا ئېرىشتى.","u esiri bilen pulitsér mukapatigha érishti."]],"智神星":[["智神星是太阳系中体积较大的行星之一。","پاللاس قۇياش سىستېمىسىدىكى ھەجىمى بىر قەدەر چوڭ پلانېتالارنىڭ بىرىدۇر.","pallas quyash sistémisidiki hejimi bir qeder chong planétalarning biridur."]],"书挡":[["书挡用来固定书页。","كىتاب تۇتقۇچ كىتاب بەتلىرىنى مۇقىملاشتۇرۇش ئۈچۈن ئىشلىتىلىدۇ.","kitab tutquch kitab betlirini muqimlashturush üchün ishlitilidu."]],"暴雪鹱":[["这种鸟被称为暴雪鹱，生活在南极。","بۇ قۇش بوران-قار قۇشى دەپ ئاتىلىپ، جەنۇبىي قۇتۇپتا ياشايدۇ.","bu qush boran-qar qushi dep atilip, jenubiy qutupta yashaydu."]],"会试":[["会试是古代科举的重要环节。","ئىمتىھان قەدىمكى دەۋردىكى ئىمتىھان تۈزۈمىنىڭ مۇھىم بىر ھالقىسى.","imtihan qedimki dewrdiki imtihan tüzümining muhim bir halqisi."]],"会展":[["会展中心即将举办国际展览。","كۆرگەزمە مەركىزى خەلقئارا كۆرگەزمىنى ئۆتكۈزمەكچى.","körgezme merkizi xelq'ara körgezmini ötküzmekchi."]],"会幕":[["会幕是古代举行仪式的场所。","ئۇچرىشىش چېدىرى قەدىمكى زاماندا مۇراسىم ئۆتكۈزىدىغان جاي ئىدى.","uchrishish chédiri qedimki zamanda murasim ötküzidighan jay idi."]],"有百利而无一害":[["这项政策有百利而无一害，值得推行。","بۇ سىياسەتنىڭ پايدىسى بار، زىيىنى يوق، ئىجرا قىلىشقا ئەرزىيدۇ.","bu siyasetning paydisi bar, ziyini yoq, ijra qilishqa erziydu."]],"朝鲜人":[["朝鲜人勤劳勇敢，以坚韧著称。","چاۋشيەنلىكلەر ئەمگەكچان ۋە باتۇر، چىدامچانلىقى بىلەن تونۇلغان.","chawshyenlikler emgekchan we batur, chidamchanliqi bilen tonulghan."]],"有百害而无一利":[["这种习惯有百害而无一利，必须改掉。","بۇ خىل ئادەتنىڭ زىيىنى كۆپ، پايدىسى يوق، چوقۇم تۈزىتىش كېرەك.","bu xil adetning ziyini köp, paydisi yoq, choqum tüzitish kérek."]],"未知":[["宇宙中还有许多未知。","ئالەمدە يەنە نۇرغۇن نامەلۇم نەرسىلەر بار.","alemde yene nurghun namelum nersiler bar."]],"末了":[["事情到了末了，大家都松了一口气。","ئىش ئاخىرلاشقاندا، ھەممەيلەن يېنىك نەپەس ئالدى.","ish axirlashqanda, hemmeylen yénik nepes aldi."]],"李代数":[["李代数是数学分支。","لى ئالگېبرا ماتېماتىكىنىڭ بىر تارمىقى.","li algébra matématikining bir tarmiqi."]],"李先念":[["李先念曾担任国家重要职务。","لى شيەننىيەن دۆلەتنىڭ مۇھىم ۋەزىپىسىنى ئۆتىگەن.","li shyenniyen döletning muhim wezipisini ötigen."]],"杖刑":[["古代杖刑非常残酷。","قەدىمكى زاماندا تاياق جازاسى بەك رەھىمسىز ئىدى.","qedimki zamanda tayaq jazasi bek rehimsiz idi."]],"李安":[["李安是一位国际知名的导演。","لى ئەن خەلقئارادا تونۇلغان بىر رېژىسسور.","li en xelq'arada tonulghan bir rézhissor."]],"李后主":[["李后主是南唐的最后一位皇帝。","لى خۇجۇ جەنۇبىي تاڭ سۇلالىسىنىڭ ئەڭ ئاخىرقى ئىمپېراتورى.","li xuju jenubiy tang sulalisining eng axirqi impératori."]],"李昉":[["李昉编纂了《太平广记》。","لى فاڭ «تەيپىڭ گۇاڭجى»نى تۈزۈپ چىققان.","li fang «teyping guangji»ni tüzüp chiqqan."]],"李丽珊":[["李丽珊是香港的特首。","لى لىشەن شياڭگاڭنىڭ ئالاھىدە مەمۇرىي رايون باشلىقى.","li lishen shyanggangning alahide memuriy rayon bashliqi."]],"林州市":[["林州市位于河南省的西北部。","لىنجو شەھىرى خېنەن ئۆلكىسىنىڭ شىمالىي غەربىدە جايلاشقان.","linjo shehiri xénen ölkisining shimaliy gherbide jaylashqan."]],"板蓝根":[["板蓝根有清热解毒的作用。","تاختا لەڭگەن يىلتىزىنىڭ ئىسسىقنى چىقىرىش ۋە زەھەرنى قايتۇرۇش رولى بار.","taxta lenggen yiltizining issiqni chiqirish we zeherni qayturush roli bar."]],"林冲":[["林冲在雪夜中独自赶路。","لىن چۇڭ قارلىق كېچىدە يالغۇز يول ماڭدى.","lin chung qarliq kéchide yalghuz yol mangdi."]],"朵颐":[["他看到美食便忍不住朵颐。","ئۇ تائامنى كۆرۈپلا ئۆزىنى تۇتۇپ قالالماي چوڭقۇر يېدى.","u taamni körüpla özini tutup qalalmay chongqur yédi."]],"李季兰":[["李季兰是一位才华横溢的诗人。","لى جىلەن ئىقتىدارلىق بىر شائىر.","li jilen iqtidarliq bir shair."]],"柘弓":[["古代战士常用柘弓进行射击。","قەدىمكى جەڭچىلەر كۆپىنچە جې ئوقيىسى بىلەن ئېتىش قىلاتتى.","qedimki jengchiler köpinche jé oqyisi bilen étish qilatti."]],"柄政":[["柄政指掌握政权。","بىڭجېڭ ھاكىمىيەتنى قولغا ئېلىشنى كۆرسىتىدۇ.","bingjéng hakimiyetni qolgha élishni körsitidu."]],"柯萨奇病毒":[["柯萨奇病毒是一种常见的肠道病毒。","كوكساكى ۋىرۇسى بىر خىل كۆپ ئۇچرايدىغان ئۈچەي ۋىرۇسىدۇر.","koksaki wirusi bir xil köp uchraydighan üchey wirusidur."]],"柳雷鸟":[["柳雷鸟是一种色彩斑斓的鸟类。","ليۇلېي قۇشى بىر خىل رەڭدار قۇش.","lyuléy qushi bir xil rengdar qush."]],"柴可夫斯基":[["柴可夫斯基创作了许多经典交响乐。","چايكوۋسكىي نۇرغۇن كلاسسىك سىمفونىيە ئىجاد قىلغان.","chaykowskiy nurghun klassik simfoniye ijad qilghan."]],"枯叶剂":[["枯叶剂常被用于农业中加速落叶。","قۇرۇق ياپراق دورىسى يېزا ئىگىلىكىدە ياپراق تۆكۈلۈشىنى تېزلىتىش ئۈچۈن كۆپ ئىشلىتىلىدۇ.","quruq yapraq dorisi yéza igilikide yapraq tökülüshini tézlitish üchün köp ishlitilidu."]],"核工业部":[["核工业部负责管理核领域事务。","يادرو سانائەت مىنىستىرلىقى يادرو ساھەسىدىكى ئىشلارنى باشقۇرۇشقا مەسئۇل.","yadro sanaet ministirliqi yadro sahesidiki ishlarni bashqurushqa mes'ul."]],"格洛纳斯":[["格洛纳斯是俄罗斯的导航系统。","گلوناس رۇسىيەنىڭ يول باشلاش سىستېمىسى.","glonas rusiyening yol bashlash sistémisi."]],"柳林县":[["柳林县是山西省的一个县，以煤炭资源和农业为主。","ليۇلىن ناھىيىسى شەنشى ئۆلكىسىدىكى بىر ناھىيە بولۇپ، كۆمۈر بايلىقى ۋە يېزا ئىگىلىكى ئاساس قىلىنىدۇ.","lyulin nahiyisi shenshi ölkisidiki bir nahiye bolup, kömür bayliqi we yéza igiliki asas qilinidu."]],"格拉茨":[["格拉茨是一座历史悠久的城市。","گراتس ئۇزۇن تارىخقا ئىگە بىر شەھەر.","grats uzun tarixqa ige bir sheher."]],"梵蒂冈":[["梵蒂冈面积很小。","فەنزە تىبەت شەھىرىنىڭ كۆلىمى بەك كىچىك.","fenze tibet shehirining kölimi bek kichik."]],"棉裤":[["这条棉裤非常保暖舒适。","بۇ پاختا ئىشتان بەك ئىسسىق ۋە راھەت.","bu paxta ishtan bek issiq we rahet."]],"棕眉柳莺":[["棕眉柳莺喜欢在灌木丛中觅食。","قوڭۇر قاشلىق تال چىمپىقى پاتىقانلىقتا يېمەك ئىزدەشنى ياخشى كۆرىدۇ.","qongur qashliq tal chimpiqi patiqanliqta yémek izdeshni yaxshi köridu."]],"棕背伯劳":[["棕背伯劳以昆虫为主要食物。","قوڭۇر دۈمبىلىك قارغۇچى قۇش ئاساسلىق يېمەكلىك قىلىپ ھاشاراتلارنى يەيدۇ.","qongur dümbilik qarghuchi qush asasliq yémeklik qilip hasharatlarni yeydu."]],"极东":[["极东地区气候寒冷。","قۇتۇپ شەرق رايونىنىڭ ھاۋاسى سوغۇق.","qutup sherq rayonining hawasi soghuq."]],"槵子":[["这种槵子木常用于制作家具。","بۇ خۇەنزى ياغىچى كۆپىنچە ئۆي جاھازىلىرى ياساشتا ئىشلىتىلىدۇ.","bu xuenzi yaghichi köpinche öy jahaziliri yasashta ishlitilidu."]],"乐事":[["周末参加音乐节真是一件乐事。","ھەپتە ئاخىرىدا مۇزىكا بايرىمىغا قاتنىشىش ھەقىقەتەن بىر خۇشاللىقتۇر.","hepte axirida muzika bayrimigha qatnishish heqiqeten bir xushalliqtur."]],"梭哈":[["他决定梭哈，赌上全部身家。","ئۇ پۈتۈن بايلىقىنى تىكىپ، ھەممىسىنى ئوتتۇرىغا قويۇشقا قارار قىلدى.","u pütün bayliqini tikip, hemmisini otturigha qoyushqa qarar qildi."]],"乐律":[["乐律是古代音乐理论的重要组成部分。","مۇزىكا قانۇنىيىتى قەدىمكى مۇزىكا نەزەرىيىسىنىڭ مۇھىم تەركىبىي قىسمى.","muzika qanuniyiti qedimki muzika nezeriyisining muhim terkibiy qismi."]],"乐手":[["这位乐手在乐队中担任主唱。","بۇ مۇزىكانت ئوركېستىردا باش ناخشىچى بولۇپ ۋەزىپە ئۆتەيدۇ.","bu muzikant orkéstirda bash naxshichi bolup wezipe öteydu."]],"楔尾鸥":[["楔尾鸥是一种海鸟，尾部呈楔形。","تارغاق قۇيرۇق چاغىسى دېڭىز قۇشى بولۇپ، قۇيرۇقى تارغاقسىمان.","targhaq quyruq chaghisi déngiz qushi bolup, quyruqi targhaqsiman."]],"楹联":[["门上贴着一副精美的楹联。","ئىشىككە بىر جۈپ نەپىس يىڭليەن ئېسىلغان.","ishikke bir jüp nepis yinglyen ésilghan."]],"树葬":[["树葬是一种环保的安葬方式。","دەرەخ دەپنىسى مۇھىت ئاسرايدىغان بىر خىل دەپنە ئۇسۇلىدۇر.","derex depnisi muhit asraydighan bir xil depne usulidur."]],"欲取姑予":[["欲取姑予是一种策略。","ئېلىشنى خالىساڭ ئاۋۋال بەرگىن دېگەن بىر ئىستراتېگىيەدۇر.","élishni xalisang awwal bergin dégen bir istratégiyedur."]],"歧异":[["歧异指观点或意见的不同。","پەرقلىقلىق كۆز قاراش ياكى پىكىرنىڭ ئوخشىماسلىقىنى كۆرسىتىدۇ.","perqliqliq köz qarash yaki pikirning oxshimasliqini körsitidu."]],"历史剧":[["这部历史剧生动再现了古代战争。","بۇ تارىخىي تىياتىر قەدىمكى ئۇرۇشنى جانلىق ئەكس ئەتتۈردى.","bu tarixiy tiyatir qedimki urushni janliq eks ettürdi."]],"死翘翘":[["他因劳累而死翘翘了。","ئۇ ھارغىنلىقتىن ئۆلۈپ كەتتى.","u harghinliqtin ölüp ketti."]],"正态分布":[["正态分布是统计学中的基础概念。","نورمال تەقسىمات ستاتىستىكىدىكى ئاساسىي چۈشەنچەدۇر.","normal teqsimat statistikidiki asasiy chüshenchedur."]],"正当理由":[["他提供了正当理由。","ئۇ قانۇنىي سەۋەب كۆرسەتتى.","u qanuniy seweb körsetti."]],"母质":[["母质是土壤形成的原始物质。","ئانا ماتېرىيالى تۇپراق شەكىللەنشىنىڭ ئەسلىي ماددىسىدۇر.","ana matériyali tupraq shekillenshining esliy maddisidur."]],"归位":[["他终于归位，恢复秩序。","ئۇ ئاخىرى ئورنىغا قايتىپ، تەرتىپنى ئەسلىگە كەلتۈردى.","u axiri ornigha qaytip, tertipni eslige keltürdi."]],"毛茶":[["毛茶是未经加工的原茶。","خام چاي بىر تەرەپ قىلىنمىغان خام چاي.","xam chay bir terep qilinmighan xam chay."]],"残余物":[["残余物被妥善存放。","قالدۇق ماددىلار مۇۋاپىق ساقلانغان.","qalduq maddilar muwapiq saqlanghan."]],"氰氨化钙":[["氰氨化钙常用于农业中的肥料。","كالتسىي سىيانامىد يېزا ئىگىلىكىدە ئوغۇت سۈپىتىدە كۆپ ئىشلىتىلىدۇ.","kaltsiy siyanamid yéza igilikide oghut süpitide köp ishlitilidu."]],"比量":[["他比量了一下衣服的尺寸。","ئۇ كىيىمنىڭ ئۆلچىمىنى سېلىشتۇرۇپ كۆردى.","u kiyimning ölchimini sélishturup kördi."]],"水路":[["这条水路是连接两地的主要通道。","بۇ سۇ يولى ئىككى جايىنى تۇتاشتۇرىدىغان ئاساسلىق يول.","bu su yoli ikki jayini tutashturidighan asasliq yol."]],"水利工程":[["水利工程是指用于控制水资源的工程设施。","سۇ ئىنشائاتى قۇرۇلۇشى سۇ بايلىقىنى كونترول قىلىدىغان قۇرۇلۇش ئەسلىھەلىرىنى كۆرسىتىدۇ.","su inshaati qurulushi su bayliqini kontrol qilidighan qurulush eslihelirini körsitidu."]],"汗液":[["汗液能帮助身体降温。","تەر بەدەن تېمپېراتۇرىسىنى تۆۋەنلىتىشكە ياردەم قىلىدۇ.","ter beden témpératurisini töwenlitishke yardem qilidu."]],"气量":[["气量大小反映一个人的胸怀宽广度。","كۆڭۈل كەڭلىكى كىشىنىڭ كۆكرەك كەڭلىكىنى ئەكس ئەتتۈرىدۇ.","köngül kengliki kishining kökrek kenglikini eks ettüridu."]],"沃州":[["沃州是瑞士的一个联邦州。","ۋو جۇ شۋېيتسارىيىنىڭ بىر فېدېراتسىيە ئىشتىتى.","wo ju shwéytsariyining bir fédératsiye ishtiti."]],"氹仔":[["氹仔是澳门的一个岛屿。","دامزا ماكاۋنىڭ بىر ئارىلى.","damza makawning bir arili."]],"沙巴":[["沙巴是马来西亚的州。","سابا مالايسىيەنىڭ بىر ئوبلاستى.","saba malaysiyening bir oblasti."]],"沙暴":[["沙暴来袭时能见度极低。","قۇم بورىنى كەلگەندە كۆرۈش دەرىجىسى ئىنتايىن تۆۋەن.","qum borini kelgende körüsh derijisi intayin töwen."]],"河南县":[["河南县是青海省的一个县。","خېنەن ناھىيىسى چىڭخەي ئۆلكىسىنىڭ بىر ناھىيىسى.","xénen nahiyisi chingxey ölkisining bir nahiyisi."]],"油气":[["油气资源是国家的重要能源。","نېفىت-تەبىئىي گاز بايلىقى دۆلەتنىڭ مۇھىم ئېنېرگىيىسىدۇر.","néfit-tebiiy gaz bayliqi döletning muhim énérgiyisidur."]],"法兰":[["法兰是一种金属材料。","فالاڭ بىر مېتال ماتېرىيال.","falang bir métal matériyal."]],"法兰克福证券交易所":[["法兰克福证券交易所历史悠久。","فاراڭكفۇرت پاي چېكى بىرژىسى ئۇزۇن تارىخقا ئىگە.","farangkfurt pay chéki birzhisi uzun tarixqa ige."]],"求职者":[["求职者需要准备好简历。","خىزمەت ئىلتىماس قىلغۇچى تەرجىمىھالىنى تەييارلىشى كېرەك.","xizmet iltimas qilghuchi terjimihalini teyyarlishi kérek."]],"波美拉尼亚":[["波美拉尼亚位于德国东部。","بومېرانىيە گېرمانىيەنىڭ شەرقىدە جايلاشقان.","boméraniye gérmaniyening sherqide jaylashqan."]],"泥刀":[["泥刀是一种传统的工具。","لاي پىچاق ئەنئەنىۋى بىر قورال.","lay pichaq en'eniwi bir qoral."]],"洛可可":[["洛可可风格充满浪漫气息。","روكوكو ئۇسلۇبى رومانتىك ھېسسىياتقا تولغان.","rokoko uslubi romantik héssiyatqa tolghan."]],"洛子峰":[["洛子峰是珠穆朗玛峰的邻近峰。","لوتسې چوققىسى جۇمۇلاڭما چوققىسىغا قوشنا چوققىدۇر.","lotsé choqqisi jumulangma choqqisigha qoshna choqqidur."]],"洗染店":[["洗染店可以修改衣服颜色。","كىيىم بويايدىغان دۇكان كىيىملەرنىڭ رەڭگىنى ئۆزگەرتەلەيدۇ.","kiyim boyaydighan dukan kiyimlerning renggini özgerteleydu."]],"流鼻涕":[["感冒时常常会流鼻涕。","زۇكام بولغاندا كۆپىنچە بۇرۇندىن سۇ ئېقىدۇ.","zukam bolghanda köpinche burundin su éqidu."]],"流窜":[["罪犯流窜多个地区作案。","جىنايەتچى ئاقارلىق بىلەن نۇرغۇن رايونلاردا جىنايەت سادىر قىلدى.","jinayetchi aqarliq bilen nurghun rayonlarda jinayet sadir qildi."]],"活化":[["活化技术能提升细胞活力。","ئاكتىپلاشتۇرۇش تېخنىكىسى ھۈجەيرە جانلىقلىقىنى ئۆستۈرەلەيدۇ.","aktiplashturush téxnikisi hüjeyre janliqliqini östüreleydu."]],"消元":[["消元是数学中常用的方法。","يوقىتىش ماتېماتىكىدا كۆپ ئىشلىتىلىدىغان ئۇسۇل.","yoqitish matématikida köp ishlitilidighan usul."]],"海纳百川":[["海纳百川，有容乃大。","دېڭىز يۈز ئۆرۈمنى سىغدۇرىدۇ، سىغدۇرۇشچانلىقى چوڭ بولغاندا ئۇلۇغ بولىدۇ.","déngiz yüz örümni sighduridu, sighdurushchanliqi chong bolghanda ulugh bolidu."]],"淋巴瘤":[["淋巴瘤是一种常见的癌症类型。","لىمفوم ئادەتتە كۆرۈلىدىغان راك تۈرى.","limfom adette körülidighan rak türi."]],"清水河县":[["清水河县位于内蒙古自治区。","چىڭشۈيخې ناھىيىسى ئىچكى موڭغۇل ئاپتونوم رايونىدا جايلاشقان.","chingshüyxé nahiyisi ichki mongghul aptonom rayonida jaylashqan."]],"浑身上下":[["他浑身上下沾满了泥。","ئۇ باش-ئايىغىچە لايغا بويىلىپ كەتتى.","u bash-ayighiche laygha boyilip ketti."]],"溜旱冰":[["她学会了溜旱冰的技巧。","ئۇ تېيىلىش ماھارىتىنى ئۆگەندى.","u téyilish maharitini ögendi."]],"溶血病":[["溶血病可能由遗传因素引起。","قان ئېرىش كېسىلى ئىرسىيەت ئامىللىرى تەرىپىدىن كەلتۈرۈپ چىقىرىلىشى مۇمكىن.","qan érish késili irsiyet amilliri teripidin keltürüp chiqirilishi mumkin."]],"滇红":[["滇红是中国著名的红茶。","دىەنخوڭ جۇڭگونىڭ مەشھۇر قىزىل چېيى.","dienxong junggoning meshhur qizil chéyi."]],"汤原":[["汤原是个宁静的小镇。","تويۈەن تىنچ بىر كىچىك بازاردۇر.","toyüen tinch bir kichik bazardur."]],"满眼":[["满眼的绿色让人心情愉悦，仿佛置身于森林之中。","كۆز ئالدىدىكى يېشىللىق كىشىنىڭ كۆڭلىنى خۇشال قىلىپ، ئۆزىنى ئورمان ئىچىدە تۇرغاندەك ھېس قىلدۇرىدۇ.","köz aldidiki yéshilliq kishining könglini xushal qilip, özini orman ichide turghandek hés qilduridu."]],"渐趋":[["他的成绩逐渐趋于稳定。","ئۇنىڭ نەتىجىسى تەدرىجىي مۇقىملاشماقتا.","uning netijisi tedrijiy muqimlashmaqta."]],"潢川":[["潢川是著名的文化名城。","خۇاڭچۈەن داڭلىق مەدەنىيەت شەھىرى.","xuangchüen dangliq medeniyet shehiri."]],"澄迈县":[["澄迈县位于海南省的北部。","چېڭماي ناھىيىسى خەينەن ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","chéngmay nahiyisi xeynen ölkisining shimalida jaylashqan."]],"滴道区":[["滴道区位于鼻腔的深处。","تامچە يول رايونى بۇرۇن بوشلۇقىنىڭ چوڭقۇر جايىدا جايلاشقان.","tamche yol rayoni burun boshluqining chongqur jayida jaylashqan."]],"泻湖":[["泻湖是海水与淡水交汇的湖泊。","لاگۇنا دېڭىز سۈيى بىلەن تاتلىق سۇ ئۇچرىشىدىغان كۆل.","laguna déngiz süyi bilen tatliq su uchrishidighan köl."]],"滥杀":[["滥杀无辜是战争中最令人发指的罪行。","گۇناھسىز ئادەملەرنى رەھىمسىز ئۆلتۈرۈش ئۇرۇشتا ئەڭ نەپرەتلىك جىنايەت.","gunahsiz ademlerni rehimsiz öltürüsh urushta eng nepretlik jinayet."]],"灌木林":[["这片灌木林是多种鸟类的栖息地。","بۇ چاتقاللىق ئورمان كۆپ خىل قۇشلارنىڭ ماكانى.","bu chatqalliq orman köp xil qushlarning makani."]],"火盆":[["火盆里燃着旺火，温暖了整个屋子。","ئوت داسقىدا كۈچلۈك ئوت يېنىپ، پۈتۈن ئۆينى ئىسسىتتى.","ot dasqida küchlük ot yénip, pütün öyni issitti."]],"炭疽菌苗":[["接种炭疽菌苗可以有效预防感染。","كۆمۈر تامچىسى ۋاكسىنىسىنى ئەملەش يۇقۇملىنىشنىڭ ئالدىنى ئېلىشتا ئۈنۈملۈك.","kömür tamchisi waksinisini emlesh yuqumlinishning aldini élishta ünümlük."]],"烤烟":[["烤烟需要经过特殊的处理。","كۆيۈك تاماكىنى ئالاھىدە بىر تەرەپ قىلىش كېرەك.","köyük tamakini alahide bir terep qilish kérek."]],"无痛":[["手术过程无痛。","ئوپېراتسىيە جەريانى ئاغرىقسىز.","opératsiye jeryani aghriqsiz."]],"无止尽":[["这种痛苦似乎无止尽。","بۇنداق ئازاب ئاخىرسىز دەك تۇيۇلىدۇ.","bundaq azab axirsiz dek tuyulidu."]],"无所不谈":[["他们无所不谈，从生活到工作。","ئۇلار ھەممە ئىش توغرىسىدا، تۇرمۇشتىن تارتىپ خىزمەتكىچە پاراڭلىشىدۇ.","ular hemme ish toghrisida, turmushtin tartip xizmetkiche paranglishidu."]],"无所用心":[["他做事无所用心，敷衍了事。","ئۇ ئىش قىلغاندا دىققەت قىلماي، ئۈستى-ئۈستى قىلىپ تاشلايدۇ.","u ish qilghanda diqqet qilmay, üsti-üsti qilip tashlaydu."]],"熊包":[["他是个典型的熊包，爱占小便宜。","ئۇ تىپىك قورقۇنچاق بولۇپ، كىچىك پايدىلاردىن پۇرسەت تەپمەيدۇ.","u tipik qorqunchaq bolup, kichik paydilardin purset tepmeydu."]],"烟消云散":[["多年恩怨终烟消云散，重归于好。","كۆپ يىللىق ئۆچمەنلىك ئاخىرى تۈگەپ، ئىناقلىشىپ قالدى.","köp yilliq öchmenlik axiri tügep, inaqliship qaldi."]],"烛架":[["烛架用来固定蜡烛，防止其倾倒。","شام قۇرۇلمىسى شامنى مۇقىملاشتۇرۇشقا، ئۇنىڭ يىقىلىشىنىڭ ئالدىنى ئېلىشقا ئىشلىتىلىدۇ.","sham qurulmisi shamni muqimlashturushqa, uning yiqilishining aldini élishqa ishlitilidu."]],"无毛":[["这只猫全身无毛，非常罕见。","بۇ مۈشۈكنىڭ پۈتۈن بەدىنى تۈكسىز، ئىنتايىن ئاز ئۇچرايدۇ.","bu müshükning pütün bedini tüksiz, intayin az uchraydu."]],"牛角挂书":[["牛角挂书形容勤学苦读。","كالا مۈڭگۈزىگە كىتاب ئېسىش ئىجتىھات بىلەن ئوقۇشنى تەسۋىرلەيدۇ.","kala münggüzige kitab ésish ijtihat bilen oqushni teswirleydu."]],"父爱":[["父爱如山，深沉而伟大。","ئاتىنىڭ مېھرى تاغدەك ئېغىر، چوڭقۇر ۋە ئۇلۇغدۇر.","atining méhri taghdek éghir, chongqur we ulughdur."]],"爽身粉":[["涂点爽身粉。","ئازغىنە بەدەن پۇدرىسى سۈركەش.","azghine beden pudrisi sürkesh."]],"牡丹江市":[["牡丹江市是黑龙江省城市。","مۇدىن جياڭ شەھىرى خېيلۇڭجياڭ ئۆلكىسىنىڭ شەھىرى.","mudin jyang shehiri xéylungjyang ölkisining shehiri."]],"王敦":[["王敦是东晋时期的权臣。","ۋاڭ دۇن شەرقىي جىن دەۋرىدىكى ھوقۇقلۇق ئەمەلدار ئىدى.","wang dun sherqiy jin dewridiki hoquqluq emeldar idi."]],"玉龙纳西族自治县":[["玉龙纳西族自治县风景优美。","يۈلۇڭ ناخى ئاپتونوم ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","yülung naxi aptonom nahiyisining menzirisi güzel."]],"献殷勤":[["她不断献殷勤讨好对方。","ئۇ ئۇنىڭغا ياراملىق كۆرۈنۈش ئۈچۈن توختىماي تىرىشتى.","u uninggha yaramliq körünüsh üchün toxtimay tirishti."]],"玉带海雕":[["玉带海雕是濒危的猛禽。","يۈدەي دېڭىز بۈركۈتى يوقالاش خەۋپىگە دۇچ كەلگەن يىرتقۇچ قۇشتۇر.","yüdey déngiz bürküti yoqalash xewpige duch kelgen yirtquch qushtur."]],"琐事":[["这些琐事让他感到十分烦恼。","بۇ ئۇششاق ئىشلار ئۇنى بەك ئاۋارە قىلدى.","bu ushshaq ishlar uni bek aware qildi."]],"琵琶鱼":[["这种琵琶鱼生活在深海之中。","بۇ خىل بېلىق تۈرى چوڭقۇر دېڭىزدا ياشايدۇ.","bu xil béliq türi chongqur déngizda yashaydu."]],"生物晶片":[["生物晶片可检测多种疾病标志物。","Biocip كۆپلىگەن كېسەللىك بەلگىلىرىنى بايقىيالايدۇ.","Biocip köpligen késellik belgilirini bayqiyalaydu."]],"田鸫":[["田鸫属于鸫科的小型鸟类。","دېڭىز قارىغۇسى تۇرغاي ئائىلىسىگە تەۋە كىچىك تىپتىكى قۇش.","déngiz qarighusi turghay ailisige tewe kichik tiptiki qush."]],"申城":[["申城是上海的旧称。","شېنچېڭ شاڭخەينىڭ كونا نامى.","shénchéng shangxeyning kona nami."]],"申扎":[["申扎位于青海省的西南部。","شېنزا چىڭخەي ئۆلكىسىنىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","shénza chingxey ölkisining jenubiy gherbiy qismida jaylashqan."]],"留芳千古":[["他的美德留芳千古。","ئۇنىڭ ئەخلاقى ئەسىرلەر بويى ئات قويىدۇ.","uning exlaqi esirler boyi at qoyidu."]],"畚箕":[["用畚箕收集落叶。","سېۋەت بىلەن قۇرۇق ياپراق يىغىڭ.","séwet bilen quruq yapraq yighing."]],"异国":[["他来到异国他乡，感到十分陌生。","ئۇ يات ئەلگە كېلىپ، ئۆزىنى ئىنتايىن يات ھېس قىلدى.","u yat elge kélip, özini intayin yat hés qildi."]],"男排":[["男排比赛今天开始。","ئەرلەر ۋوللىبول مۇسابىقىسى بۈگۈن باشلىنىدۇ.","erler wollibol musabiqisi bügün bashlinidu."]],"界标":[["界标用于标记国与国之间的边界。","چېگرا بەلگىسى دۆلەتلەر ئارىسىدىكى چېگرىنى بەلگىلەشكە ئىشلىتىلىدۇ.","chégra belgisi döletler arisidiki chégrini belgileshke ishlitilidu."]],"畏罪":[["他畏罪潜逃，最终被警方抓获。","ئۇ جىنايىتىدىن قورقۇپ قېچىپ كېتىپ، ئاخىرىدا ساقچىلار تەرىپىدىن تۇتۇلدى.","u jinayitidin qorqup qéchip kétip, axirida saqchilar teripidin tutuldi."]],"痛恶":[["他痛恶一切不道德的行为。","ئۇ ھەر قانداق ئەخلاقسىز قىلمىشلارنى ئۆچ كۆرىدۇ.","u her qandaq exlaqsiz qilmishlarni öch köridu."]],"异能":[["他拥有超常异能。","ئۇ ئادەتتىن تاشقىرى ئالاھىدە قابىلىيەتكە ئىگە.","u adettin tashqiri alahide qabiliyetke ige."]],"异乡人":[["他作为异乡人努力融入当地。","ئۇ يات يۇرتلۇق سۈپىتىدە يەرلىك جەمئىيەتكە سىڭىشكە تىرىشتى.","u yat yurtluq süpitide yerlik jem'iyetke singishke tirishti."]],"登革病毒":[["登革病毒属于黄病毒科的一员。","دېڭگى ۋىرۇسى سېرىق ۋىرۇس ئائىلىسىنىڭ بىر ئەزاسىدۇر.","dénggi wirusi sériq wirus ailisining bir ezasidur."]],"白素贞":[["白素贞是中国民间传说中的角色。","ئاق سۇجېن جۇڭگو خەلق ئەپسانىسىدىكى بىر رول.","aq sujén junggo xelq epsanisidiki bir rol."]],"白线斑蚊":[["这种白线斑蚊会传播疾病。","بۇ خىل ئاق سىزىقلىق پاشا كېسەل تارقىتىدۇ.","bu xil aq siziqliq pasha késel tarqitidu."]],"碍面子":[["他为了碍面子，硬着头皮答应了。","ئۇ يۈز-ئابرويى ئۈچۈن زورلاپ قوبۇل قىلدى.","u yüz-abroyi üchün zorlap qobul qildi."]],"硝酸":[["硝酸是一种强酸。","نىترات كۈچلۈك بىر خىل كىسلاتا.","nitrat küchlük bir xil kislata."]],"砗磲":[["砗磲是一种大型贝类。","ترىداكنا چوڭ تىپتىكى بىر خىل قۇلۇپىچە.","tridakna chong tiptiki bir xil qulupiche."]],"硫代硫酸钠":[["硫代硫酸钠用于漂白。","تىوسۇلفات ناترىي ئاقارتىشتا ئىشلىتىلىدۇ.","tiosulfat natriy aqartishta ishlitilidu."]],"碾子山区":[["碾子山区以独特的自然风光闻名。","تەگلىك تاغ رايونى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","teglik tagh rayoni özgiche tebiiy menzirisi bilen dangliq."]],"矸石":[["矸石是煤矿开采中的废弃物。","گەنشى كۆمۈر كان قېزىشتىكى تاشلاندۇق.","genshi kömür kan qézishtiki tashlanduq."]],"石林县":[["石林县以喀斯特景观闻名。","تاش ئورمان ناھىيىسى كارست مەنزىرىسى بىلەن داڭلىق.","tash orman nahiyisi karst menzirisi bilen dangliq."]],"紫荆":[["紫荆花开满整个庭院。","بىنەپشە چىلەن گۈلى پۈتۈن ھويلىنى گۈللەندۈرۈپتۇ.","binepshe chilen güli pütün hoylini güllendürüptu."]]};
